/**
 * CORE-6307 — "less is more": which explainers the assistant shows as cards.
 *
 * ONE rule for the panel's first view and the chat's improvement answer; the
 * API applies the same rule to the chat stream (doc2-api
 * `module/validation_assistant/answer_cap.py`, `MAX_SUGGESTIONS = 2`):
 *
 * 1. one explainer per target field (the first wins; server order = impact);
 * 2. the improvement offers first, then the blocker decisions with a safe change;
 * 3. at most MAX_SUGGESTIONS of them; everything else is collapsed behind ONE
 *    "N more" line.
 */
import { hasSafeChange, isBlockerDecision, type Explainer } from './explainer';
import {
  normalizeAssistantAction,
  type AssistantAction,
} from 'src/utils/validationAssistantActions';

export const MAX_SUGGESTIONS = 2;

export function dedupeByField(items: Explainer[]): Explainer[] {
  const fields = new Set<string>();
  const ids = new Set<string>();
  const out: Explainer[] = [];
  for (const item of items) {
    const key = item.offer_id || item.id;
    if (ids.has(key)) continue;
    if (item.field && fields.has(item.field)) continue;
    ids.add(key);
    if (item.field) fields.add(item.field);
    out.push(item);
  }
  return out;
}

export function selectSuggestions(
  items: Explainer[],
  max: number = MAX_SUGGESTIONS,
): { shown: Explainer[]; rest: Explainer[] } {
  const unique = dedupeByField(items);
  const offers = unique.filter((item) => !isBlockerDecision(item));
  const safe = unique.filter((item) => isBlockerDecision(item) && hasSafeChange(item));
  const shown = [...offers, ...safe].slice(0, Math.max(0, max));
  return { shown, rest: unique.filter((item) => !shown.includes(item)) };
}

// settings_action / rule_preview: title-only lines from the 7-card cap (CORE-6454)
export type CollapsedKind = 'explainer' | 'finding' | 'action' | 'settings_action' | 'rule_preview';

/** One line behind the answer's "N more" toggle (doc2-api answer_cap.compose_answer). */
export interface CollapsedItem {
  kind: CollapsedKind;
  id: string;
  offer_id: string | null;
  title: string;
  field_label: string | null;
  operation: string | null;
  pending: boolean;
  area: string | null;
  action: AssistantAction | null;
}

const KINDS: readonly CollapsedKind[] = [
  'explainer',
  'finding',
  'action',
  'settings_action',
  'rule_preview',
];

function str(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value : null;
}

export function parseCollapsedItems(value: unknown): CollapsedItem[] {
  if (!Array.isArray(value)) return [];
  const out: CollapsedItem[] = [];
  for (const raw of value) {
    if (!raw || typeof raw !== 'object') continue;
    const v = raw as Record<string, unknown>;
    const kind = KINDS.find((k) => k === v.kind);
    const id = str(v.id);
    const title = str(v.title);
    if (!kind || !id || !title) continue;
    const action = kind === 'action' ? normalizeAssistantAction(v.action) : null;
    if (kind === 'action' && !action) continue;
    out.push({
      kind,
      id,
      offer_id: str(v.offer_id),
      title,
      field_label: str(v.field_label),
      operation: str(v.operation),
      pending: v.pending === true,
      area: str(v.area),
      action,
    });
  }
  return out;
}

/** The server's count; never less than the lines that are listed. */
export function parseMoreCount(value: unknown, collapsed: CollapsedItem[]): number {
  const count = typeof value === 'number' && Number.isFinite(value) ? Math.floor(value) : 0;
  return Math.max(count, collapsed.length);
}
