// CORE-6454: the table diagnosis (doc2-api GET /v3/validation-assistant/diagnosis), parsed defensively.
import {
  toSettingsActionOffer,
  type SettingsActionOffer,
} from 'src/utils/settingsAssistant/settingsActionOffers';

export type DiagnosisSymptom =
  | 'missing_columns'
  | 'wrong_column'
  | 'wrong_amounts'
  | 'same_correction'
  | 'field_empty'
  | 'po_not_found'
  | 'unknown';

export type DiagnosisRoute = 'apply' | 'forward_to_admin' | 'none';

export interface DiagnosisEvidence {
  runs_checked: number;
  runs_without_schema: number;
  empty_columns: string[];
  example_doc_ids: string[];
  window_days: number;
}

export interface DiagnosisSentence {
  de: string;
  en: string;
}

export interface DiagnosisFinding {
  code: string;
  lever: string;
  rank: number;
  evidence: DiagnosisEvidence;
  sentence: DiagnosisSentence;
  can_apply: boolean;
  route: DiagnosisRoute;
  offer_id?: string | null;
  /** Legacy admin preview from apply_hint; newer APIs create it on click. */
  settings_offer?: SettingsActionOffer | null;
}

export interface DiagnosisResult {
  doc_id: string;
  table_name: string | null;
  supplier_label: string | null;
  language: string;
  findings: DiagnosisFinding[];
}

export interface AiTagCandidate {
  tag: string;
  column_name: string;
  column_label: string;
  matched_via: string;
  confidence: string;
}

export interface AiTagSuggestion {
  table_name: string | null;
  current_tags: string[];
  candidates: AiTagCandidate[];
  not_a_tag: { reason: string; sentence: DiagnosisSentence } | null;
}

export const SYMPTOM_CHIPS: { symptom: DiagnosisSymptom; key: string }[] = [
  { symptom: 'missing_columns', key: 'validation_assistant_diagnosis_chip_missing_columns' },
  { symptom: 'wrong_column', key: 'validation_assistant_diagnosis_chip_wrong_column' },
  { symptom: 'wrong_amounts', key: 'validation_assistant_diagnosis_chip_wrong_amounts' },
  { symptom: 'po_not_found', key: 'validation_assistant_diagnosis_chip_po_not_found' },
  { symptom: 'unknown', key: 'validation_assistant_diagnosis_chip_unknown' },
];

export const LEVER_AI_TAGS = 'ai_tags';
export const LEVER_STRUCTURED_OUTPUT_SUPPLIER = 'structured_output_supplier';
export const MAX_EXAMPLE_DOCS = 3;

const ROUTES: readonly DiagnosisRoute[] = ['apply', 'forward_to_admin', 'none'];

function str(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value : null;
}

function num(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value) ? Math.max(0, Math.floor(value)) : 0;
}

function strings(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((item): item is string => !!str(item)) : [];
}

function toSentence(value: unknown): DiagnosisSentence | null {
  if (!value || typeof value !== 'object') return null;
  const v = value as Record<string, unknown>;
  const de = str(v.de);
  const en = str(v.en);
  if (!de && !en) return null;
  return { de: de || en || '', en: en || de || '' };
}

function toEvidence(value: unknown): DiagnosisEvidence {
  const v = (value && typeof value === 'object' ? value : {}) as Record<string, unknown>;
  return {
    runs_checked: num(v.runs_checked),
    runs_without_schema: num(v.runs_without_schema),
    empty_columns: strings(v.empty_columns),
    example_doc_ids: strings(v.example_doc_ids).slice(0, MAX_EXAMPLE_DOCS),
    window_days: num(v.window_days),
  };
}

function hintOfferId(hint: unknown): string | null {
  if (!hint || typeof hint !== 'object') return null;
  const h = hint as Record<string, unknown>;
  return h.type === 'improvement_offer' ? str(h.offer_id) : null;
}

function hintSettingsOffer(hint: unknown, docId: string): SettingsActionOffer | null {
  if (!hint || typeof hint !== 'object') return null;
  if ((hint as Record<string, unknown>).type !== 'settings_actions') return null;
  return toSettingsActionOffer(hint, docId ? { doc_id: docId } : {});
}

export function parseDiagnosisFinding(value: unknown, docId = ''): DiagnosisFinding | null {
  if (!value || typeof value !== 'object') return null;
  const v = value as Record<string, unknown>;
  const code = str(v.code);
  const lever = str(v.lever);
  const sentence = toSentence(v.sentence);
  const route = ROUTES.find((r) => r === v.route);
  if (!code || !lever || !sentence || !route) return null;
  return {
    code,
    lever,
    rank: num(v.rank),
    evidence: toEvidence(v.evidence),
    sentence,
    can_apply: v.can_apply === true,
    route,
    offer_id: str(v.offer_id) || hintOfferId(v.apply_hint),
    settings_offer: hintSettingsOffer(v.apply_hint, docId),
  };
}

export function parseDiagnosis(value: unknown): DiagnosisResult | null {
  if (!value || typeof value !== 'object') return null;
  const v = value as Record<string, unknown>;
  if (v.success === false) return null;
  const docId = str(v.doc_id) || '';
  const findings = (Array.isArray(v.findings) ? v.findings : [])
    .map((item) => parseDiagnosisFinding(item, docId))
    .filter((f): f is DiagnosisFinding => !!f)
    .sort((a, b) => a.rank - b.rank);
  return {
    doc_id: docId,
    table_name: str(v.table_name),
    supplier_label: str(v.supplier_label),
    language: str(v.language) || 'en',
    findings,
  };
}

export function parseAiTagSuggestion(value: unknown): AiTagSuggestion | null {
  if (!value || typeof value !== 'object') return null;
  const v = value as Record<string, unknown>;
  if (v.success === false) return null;
  const candidates: AiTagCandidate[] = [];
  for (const raw of Array.isArray(v.candidates) ? v.candidates : []) {
    if (!raw || typeof raw !== 'object') continue;
    const c = raw as Record<string, unknown>;
    const tag = str(c.tag);
    if (!tag) continue;
    candidates.push({
      tag,
      column_name: str(c.column_name) || '',
      column_label: str(c.column_label) || str(c.column_name) || tag,
      matched_via: str(c.matched_via) || '',
      confidence: str(c.confidence) || '',
    });
  }
  const notATag = v.not_a_tag as Record<string, unknown> | null | undefined;
  const notSentence = notATag ? toSentence(notATag.sentence) : null;
  return {
    table_name: str(v.table_name),
    current_tags: strings(v.current_tags),
    candidates,
    not_a_tag: notATag && notSentence ? { reason: str(notATag.reason) || '', sentence: notSentence } : null,
  };
}

// de and en come from the server; every other UI language reads en
export function sentenceFor(sentence: DiagnosisSentence, language: string): string {
  return language.slice(0, 2).toLowerCase() === 'de' ? sentence.de : sentence.en;
}

// what the clerk forwards; the explainer emits the matching offer
export function diagnosisOfferId(finding: DiagnosisFinding): string {
  return finding.offer_id || `diagnosis:${finding.code}`;
}

export type DiagnosisButton = 'show_tags' | 'settings_action' | 'forward';

export function diagnosisButtons(finding: DiagnosisFinding): DiagnosisButton[] {
  if (finding.route === 'forward_to_admin') return ['forward'];
  if (finding.route !== 'apply') return [];
  if (finding.lever === LEVER_AI_TAGS) return ['show_tags'];
  if (finding.lever === LEVER_STRUCTURED_OUTPUT_SUPPLIER)
    return ['settings_action'];
  return [];
}

// --- AI tag preview (POST /v3/validation-assistant/ai-tags/preview) ---

export type AiTagVerdict = 'ok' | 'partial' | 'failed' | 'stopped';

export interface AiTagPreviewDocument {
  doc_id: string;
  is_current: boolean;
  row_count: number;
  before: Record<string, number>;
  after: Record<string, number>;
  rows: Record<string, unknown>[];
  error: string | null;
}

export interface AiTagPreview {
  preview_token: string | null;
  expires_in_seconds: number;
  table_name: string | null;
  wanted_columns: { column_name: string; column_label: string }[];
  documents: AiTagPreviewDocument[];
  summary: { documents: number; wanted_present_in: number; columns_lost: string[] };
  verdict: AiTagVerdict;
  rounds_left: number;
  /** stopped only: the server's sentence for the clerk */
  sentence: DiagnosisSentence | null;
}

const VERDICTS: readonly AiTagVerdict[] = ['ok', 'partial', 'failed', 'stopped'];

function counts(value: unknown): Record<string, number> {
  const filled = (value as { filled_rows?: unknown } | null)?.filled_rows;
  if (!filled || typeof filled !== 'object') return {};
  const out: Record<string, number> = {};
  for (const [label, count] of Object.entries(filled as Record<string, unknown>)) out[label] = num(count);
  return out;
}

function wantedColumns(value: unknown): AiTagPreview['wanted_columns'] {
  return (Array.isArray(value) ? value : [])
    .map((raw) => {
      const w = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
      const name = str(w.column_name) || '';
      return { column_name: name, column_label: str(w.column_label) || name };
    })
    .filter((w) => !!w.column_label);
}

export function parseAiTagPreview(value: unknown): AiTagPreview | null {
  if (!value || typeof value !== 'object') return null;
  const v = value as Record<string, unknown>;
  const verdict = VERDICTS.find((item) => item === v.verdict);
  if (!verdict) return null;
  const documents: AiTagPreviewDocument[] = [];
  for (const raw of Array.isArray(v.documents) ? v.documents : []) {
    if (!raw || typeof raw !== 'object') continue;
    const d = raw as Record<string, unknown>;
    const docId = str(d.doc_id);
    if (!docId) continue;
    documents.push({
      doc_id: docId,
      is_current: d.is_current === true,
      row_count: num(d.row_count),
      before: counts(d.before),
      after: counts(d.after),
      rows: (Array.isArray(d.rows) ? d.rows : []).filter(
        (row): row is Record<string, unknown> => !!row && typeof row === 'object',
      ),
      error: str(d.error),
    });
  }
  const summary = (v.summary && typeof v.summary === 'object' ? v.summary : {}) as Record<string, unknown>;
  return {
    preview_token: str(v.preview_token),
    expires_in_seconds: num(v.expires_in_seconds),
    table_name: str(v.table_name),
    wanted_columns: wantedColumns(v.wanted_columns),
    documents,
    summary: {
      documents: num(summary.documents) || documents.length,
      wanted_present_in: num(summary.wanted_present_in),
      columns_lost: strings(summary.columns_lost),
    },
    verdict,
    rounds_left: num(v.rounds_left),
    sentence: toSentence(v.sentence),
  };
}

// the 429 body after two rounds: no token, the server's sentence, forward only
export function stoppedPreview(body: Record<string, unknown>): AiTagPreview {
  const payload = (body.improvement_payload || {}) as Record<string, unknown>;
  return {
    preview_token: null,
    expires_in_seconds: 0,
    table_name: str(payload.table_name),
    wanted_columns: wantedColumns(payload.wanted_columns),
    documents: [],
    summary: { documents: 0, wanted_present_in: 0, columns_lost: [] },
    verdict: 'stopped',
    rounds_left: 0,
    sentence: toSentence(payload.sentence),
  };
}
