<!-- CORE-6161: the validation screen's assistant, built from the shared AssistantChat blocks. -->
<template>
  <AssistantShell
    :aria-label="$t('validation_assistant_title')"
    test-id="validation-assistant"
    @keydown.esc.stop="$emit('close')"
  >
    <template v-if="!windowMode" #grip>
      <AssistantResizeGrip
        :model-value="gripWidth"
        :min="minWidth"
        :max="maxWidth"
        test-id="validation-assistant"
        @update:model-value="onResize"
        @reset="onResetWidth"
      />
    </template>

    <template #header>
      <AssistantHeader
        :title="$t('validation_assistant_title')"
        :show-pop-out="!windowMode && !compact"
        :new-chat-disabled="isStreaming || !turns.length"
        :close-label="$t('validation_assistant_close')"
        test-id="validation-assistant"
        @new-chat="startNewChat"
        @pop-out="$emit('pop-out')"
        @close="$emit('close')"
      />
    </template>

    <AssistantMessageList
        ref="messageList"
        test-id="validation-assistant"
        :class="{ 'validation-assistant__messages--wide': wide }"
      >
      <!-- CORE-6161 popout: a window opened standalone (no opener, no live
           screen) has nothing to work from — say so instead of a blank panel. -->
      <div
        v-if="orphaned"
        class="validation-assistant__orphaned"
        data-test="validation-assistant-orphaned"
      >
        <Icon icon="mdi:link-off" width="32" height="32" />
        <p>{{ $t('validation_assistant_window_empty') }}</p>
      </div>

      <AssistantBubble
        v-if="!orphaned"
        role="assistant"
        :content="summary"
        class="validation-assistant__board-item"
        data-test="validation-assistant-summary"
        test-id="validation-assistant"
        aria-live="polite"
      />

      <AssistantActionCard
        v-if="!orphaned && !compact && chatEnabled && !turns.length"
        class="validation-assistant__chat-item"
        data-test="validation-assistant-analysis-start"
        :title="$t('validation_assistant_question_improve')"
        test-id="validation-assistant"
      >
        <template #actions>
          <q-btn
            unelevated
            no-caps
            color="primary"
            icon="auto_awesome"
            class="validation-assistant__action-btn"
            data-test="validation-assistant-analysis-start-button"
            :disable="isStreaming"
            @click="watchImprovements"
            >{{ $t('start') }}</q-btn
          >
        </template>
      </AssistantActionCard>

      <!-- CORE-6307: at most two suggestions, the biggest impact first (server order);
           an image and one sentence each, the video only on click -->
      <p
        v-if="suggestions.length"
        class="validation-assistant__improvements-title validation-assistant__board-item"
        data-test="validation-assistant-improvements-title"
      >
        {{ countText('validation_assistant_improvements_found', suggestions.length) }}
      </p>
      <div
        v-for="item in suggestions"
        :key="'i-' + item.id"
        class="validation-assistant__board-item"
        data-test="validation-assistant-improvement-teaser"
        :data-offer-kind="item.offer_kind"
      >
        <ValidationAssistantExplainerCard
          compact
          collapsible
          :explainer="item"
          :doc-id="docId"
          :can-apply-form="canChangeFields"
          @apply="onExplainerApply"
          @apply-form="applyFormAction"
        />
      </div>

      <!-- CORE-6307: every problem without a safe change: ONE line, no video per problem -->
      <div
        v-if="collapsedCount"
        class="validation-assistant__collapsed validation-assistant__board-item"
        data-test="validation-assistant-problems-collapsed"
      >
        <q-btn
          flat
          no-caps
          dense
          align="left"
          :icon="problemsOpen ? 'expand_less' : 'expand_more'"
          class="validation-assistant__collapsed-toggle"
          :aria-expanded="problemsOpen ? 'true' : 'false'"
          :label="countText('validation_assistant_more_problems_no_safe_change', collapsedCount)"
          data-test="validation-assistant-problems-collapsed-toggle"
          @click="problemsOpen = !problemsOpen"
        />
        <ul
          v-if="problemsOpen"
          class="validation-assistant__collapsed-list"
          data-test="validation-assistant-problems-collapsed-list"
        >
          <li
            v-for="item in collapsedProblems"
            :key="'p-' + item.id"
            data-test="validation-assistant-problem-teaser"
          >
            <span class="validation-assistant__collapsed-title">{{ item.title }}</span>
            <span v-if="item.field_label" class="validation-assistant__collapsed-field">
              · {{ item.field_label }}</span
            >
            <span class="validation-assistant__collapsed-badge">{{ problemBadge(item) }}</span>
          </li>
        </ul>
      </div>

      <template v-if="!orphaned">
      <AssistantActionCard
        v-for="blocker in boardCap.blocking"
        :key="'b-' + blocker.field_name"
        class="validation-assistant__board-item"
        data-test="validation-assistant-card"
        variant="danger"
        :title="blocker.label"
        :badge="kindLabel(blocker.kind)"
        :reason="blocker.reason"
        test-id="validation-assistant"
      >
        <template #actions>
          <q-btn
            outline
            no-caps
            dense
            color="primary"
            class="validation-assistant__action-btn"
            data-test="validation-assistant-jump"
            @click="jumpToField(blocker.field_name)"
            >{{ $t('validation_assistant_jump_to_field') }}</q-btn
          >
        </template>
      </AssistantActionCard>

      <AssistantActionCard
        v-for="blocker in boardCap.hidden"
        :key="'h-' + blocker.field_name"
        class="validation-assistant__board-item"
        data-test="validation-assistant-hidden-card"
        variant="warning"
        :title="blocker.label"
        :badge="$t('validation_assistant_kind_hidden')"
        :reason="$t('validation_assistant_reason_hidden')"
        test-id="validation-assistant"
      />

      <AssistantActionCard
        v-for="(table, tableIndex) in boardCap.tables"
        :key="'t-' + tableIndex"
        class="validation-assistant__board-item"
        data-test="validation-assistant-table-card"
        variant="danger"
        :title="$t('validation_assistant_table_title')"
        :badge="$t('validation_assistant_table_count', { count: table.items.length })"
        test-id="validation-assistant"
      >
        <ul class="validation-assistant__table-list">
          <li v-for="(item, itemIndex) in table.items" :key="itemIndex">
            {{ tableItemText(item) }}
          </li>
        </ul>
        <template #actions>
          <q-btn
            outline
            no-caps
            dense
            color="primary"
            class="validation-assistant__action-btn"
            data-test="validation-assistant-jump-table"
            @click="jumpToTable(table.table_name)"
            >{{ $t('validation_assistant_jump_to_table') }}</q-btn
          >
        </template>
      </AssistantActionCard>

      <!-- CORE-6454: never more than MAX_VISIBLE_CARDS big cards on the board -->
      <div
        v-if="boardCap.rest.length"
        class="validation-assistant__collapsed validation-assistant__board-item"
        data-test="validation-assistant-board-collapsed"
      >
        <q-btn
          flat
          no-caps
          dense
          align="left"
          :icon="boardMoreOpen ? 'expand_less' : 'expand_more'"
          class="validation-assistant__collapsed-toggle"
          :aria-expanded="boardMoreOpen ? 'true' : 'false'"
          :label="countText('validation_assistant_more_items', boardCap.rest.length)"
          data-test="validation-assistant-board-collapsed-toggle"
          @click="boardMoreOpen = !boardMoreOpen"
        />
        <ul v-if="boardMoreOpen" class="validation-assistant__collapsed-list">
          <li
            v-for="item in boardCap.rest"
            :key="'bm-' + item.key"
            class="validation-assistant__collapsed-item"
            data-test="validation-assistant-board-collapsed-item"
          >
            <span class="validation-assistant__collapsed-title">{{ item.title }}</span>
            <span v-if="item.badge" class="validation-assistant__collapsed-badge">{{ item.badge }}</span>
          </li>
        </ul>
      </div>
      </template>

      <AssistantBubble
        v-for="(turn, idx) in turns"
        :key="'turn-' + idx"
        :role="turn.role"
        :content="turn.text"
        :render-markdown="renderMarkdown"
        class="validation-assistant__chat-item"
        copyable
        test-id="validation-assistant"
      >
        <template v-if="turn.role === 'system' && turn.change" #default>
          <AssistantAppliedChangeLine
            :content="turn.text"
            :undone="turn.change.undone"
            :failed="turn.change.failed"
            :undone-label="$t('validation_assistant_action_undone')"
            test-id="validation-assistant"
          >
            <template
              v-if="turn.change.canUndo && !turn.change.failed && canChangeFields"
              #action
            >
              <q-btn
                flat
                dense
                no-caps
                color="primary"
                size="sm"
                :label="$t('undo')"
                :loading="turn.change.undoing"
                :disable="!canChangeFields || turn.change.undoing"
                data-test="validation-assistant-applied-change-undo"
                @click="undoChange(turn.change)"
              />
            </template>
          </AssistantAppliedChangeLine>
        </template>

        <template
          v-if="
            turn.findings?.length ||
            turn.actions?.length ||
            turn.rulePreview ||
            turn.settingsActions?.length ||
            turn.explainers?.length ||
            turn.moreCount ||
            turn.diagnosis ||
            turn.aiTagPreview
          "
          #after
        >
          <div class="validation-assistant__action-cards">
            <!-- CORE-6454: the top cause of a table problem; the other causes go to "N more" -->
            <AssistantActionCard
              v-if="isDiagnosisVisible(turn)"
              data-test="validation-assistant-diagnosis-card"
              :data-code="turn.diagnosis!.finding.code"
              :data-route="turn.diagnosis!.finding.route"
              variant="warning"
              :kicker="$t('validation_assistant_diagnosis_kicker')"
              :title="diagnosisSentence(turn.diagnosis!.finding)"
              test-id="validation-assistant"
            >
              <ul class="validation-assistant__diagnosis-lines">
                <li
                  v-if="diagnosisEvidence(turn.diagnosis!.finding)"
                  data-test="validation-assistant-diagnosis-evidence"
                >
                  {{ diagnosisEvidence(turn.diagnosis!.finding) }}
                </li>
                <li data-test="validation-assistant-diagnosis-scope">
                  {{ diagnosisScope(turn.diagnosis!) }}
                </li>
                <li
                  v-if="diagnosisPermission(turn.diagnosis!.finding)"
                  data-test="validation-assistant-diagnosis-permission"
                >
                  {{ diagnosisPermission(turn.diagnosis!.finding) }}
                </li>
                <li
                  v-if="turn.diagnosis!.status === 'forwarded'"
                  data-test="validation-assistant-diagnosis-forwarded"
                >
                  {{ $t('validation_assistant_diagnosis_forwarded') }}
                </li>
              </ul>
              <p
                v-if="turn.diagnosis!.finding.evidence.example_doc_ids.length"
                class="validation-assistant__diagnosis-examples"
              >
                <span>{{ $t('validation_assistant_diagnosis_examples') }}</span>
                <a
                  v-for="(exampleId, exampleIndex) in turn.diagnosis!.finding.evidence.example_doc_ids"
                  :key="exampleId"
                  :href="docHref(exampleId)"
                  target="_blank"
                  rel="noopener"
                  data-test="validation-assistant-diagnosis-example"
                  >{{ $t('validation_assistant_diagnosis_example', { n: exampleIndex + 1 }) }}</a
                >
              </p>
              <template v-if="diagnosisButtonsOf(turn).length" #actions>
                <q-btn
                  v-if="diagnosisButtonsOf(turn).includes('settings_action')"
                  unelevated
                  no-caps
                  color="primary"
                  class="validation-assistant__action-btn"
                  data-test="validation-assistant-diagnosis-setting"
                  :loading="turn.diagnosis!.status === 'previewing'"
                  :disable="turn.diagnosis!.status !== 'open'"
                  @click="showDiagnosisSetting(turn)"
                  >{{ $t('validation_assistant_diagnosis_show') }}</q-btn
                >
                <q-btn
                  v-if="diagnosisButtonsOf(turn).includes('show_tags')"
                  unelevated
                  no-caps
                  color="primary"
                  class="validation-assistant__action-btn"
                  data-test="validation-assistant-diagnosis-show"
                  :loading="turn.diagnosis!.status === 'suggesting'"
                  :disable="turn.diagnosis!.status !== 'open'"
                  @click="showDiagnosisTags(turn)"
                  >{{ $t('validation_assistant_diagnosis_show') }}</q-btn
                >
                <q-btn
                  v-if="diagnosisButtonsOf(turn).includes('forward')"
                  unelevated
                  no-caps
                  color="primary"
                  class="validation-assistant__action-btn"
                  data-test="validation-assistant-diagnosis-forward"
                  :loading="turn.diagnosis!.status === 'forwarding'"
                  :disable="turn.diagnosis!.status !== 'open'"
                  @click="forwardDiagnosis(turn)"
                  >{{ $t('validation_assistant_diagnosis_forward') }}</q-btn
                >
                <q-btn
                  outline
                  no-caps
                  color="primary"
                  class="validation-assistant__action-btn"
                  data-test="validation-assistant-diagnosis-dismiss"
                  :disable="turn.diagnosis!.status !== 'open'"
                  @click="dismissDiagnosis(turn)"
                  >{{ $t('validation_assistant_diagnosis_no') }}</q-btn
                >
              </template>
            </AssistantActionCard>
            <!-- CORE-6454: the admin switches structured output on for this supplier -->
            <SettingsAssistantSettingsActionCard
              v-if="turn.diagnosis?.status === 'settings' && turn.diagnosis.finding.settings_offer"
              data-test="validation-assistant-diagnosis-settings-action"
              :offer="turn.diagnosis.finding.settings_offer"
            />
            <ValidationAssistantAiTagPreviewCard
              v-if="turn.aiTagPreview"
              :preview="turn.aiTagPreview.preview"
              :supplier-label="turn.aiTagPreview.supplierLabel"
              :language="appLanguage"
              :received-at="turn.aiTagPreview.receivedAt"
              :applied="turn.aiTagPreview.applied"
              :forwarding="turn.aiTagPreview.forwarding"
              :forwarded="turn.aiTagPreview.forwarded"
              @applied="(applied, written) => onAiTagsApplied(turn, applied, written)"
              @undone="(restored) => onAiTagsUndone(turn, restored)"
              @forward="forwardPreview(turn)"
            />
            <!-- CORE-6161: one sorted list — red, orange, neutral, then the blue jumps. -->
            <template v-for="item in turnView(turn).items" :key="item.key">
            <AssistantActionCard
              v-if="item.type === 'finding-group'"
              data-test="validation-assistant-finding-group"
              :data-severity="item.group.severity"
              :variant="severityVariant(item.group.severity)"
              :kicker="areaLabel(item.group.area)"
              :title="item.group.title"
              :badge="String(item.group.findings.length)"
              test-id="validation-assistant"
            >
              <ul class="validation-assistant__finding-group-list">
                <li
                  v-for="finding in item.group.findings"
                  :key="'f-' + finding.id"
                  class="validation-assistant__finding-group-item"
                  data-test="validation-assistant-finding-group-item"
                >
                  <span class="validation-assistant__finding-group-field">{{
                    finding.label || finding.title
                  }}</span>
                  <span
                    v-if="findingCandidates(finding)"
                    class="validation-assistant__finding-group-count"
                    >{{
                      countText(
                        'validation_assistant_finding_candidates',
                        findingCandidates(finding) || 0,
                      )
                    }}</span
                  >
                  <span
                    v-else-if="finding.message"
                    class="validation-assistant__finding-group-message"
                    >{{ finding.message }}</span
                  >
                  <q-btn
                    v-if="finding.field"
                    outline
                    no-caps
                    dense
                    size="sm"
                    color="primary"
                    class="validation-assistant__action-btn"
                    data-test="validation-assistant-finding-group-field"
                    @click="goToFindingField(finding)"
                    >{{ $t('validation_assistant_jump_to_field') }}</q-btn
                  >
                </li>
              </ul>
            </AssistantActionCard>
            <div
              v-else-if="item.type === 'finding'"
              class="validation-assistant__finding"
              :class="`validation-assistant__finding--${findingVariant(item.finding)}`"
              data-test="validation-assistant-finding-card"
              :data-severity="item.finding.severity"
            >
              <div class="validation-assistant__finding-text">
                <span
                  class="validation-assistant__finding-kicker"
                  data-test="validation-assistant-label-key"
                  >{{ areaLabel(item.finding.area) }}</span
                >
                <span class="validation-assistant__finding-title">{{
                  item.finding.title
                }}</span>
                <span v-if="item.finding.message" class="validation-assistant__finding-reason">{{
                  item.finding.message
                }}</span>
              </div>
              <div
                v-if="findingChips(item.finding).length > 1"
                class="validation-assistant__finding-chips"
                data-test="validation-assistant-finding-chips"
              >
                <button
                  v-for="chip in visibleFindingChips(item.finding)"
                  :key="chip.key"
                  type="button"
                  class="validation-assistant__finding-chip"
                  data-test="validation-assistant-finding-chip"
                  @click="jumpToField(chip.key)"
                >
                  {{ chip.label }}
                </button>
                <button
                  v-if="hiddenFindingChips(item.finding)"
                  type="button"
                  class="validation-assistant__finding-chip validation-assistant__finding-chip--more"
                  data-test="validation-assistant-finding-chips-more"
                  @click="expandedChips[item.finding.id] = true"
                >
                  +{{ hiddenFindingChips(item.finding) }}
                </button>
              </div>
              <div
                v-if="singleFindingField(item.finding) || findingDeepLink(item.finding) || findingDocLink(item.finding)"
                class="validation-assistant__finding-actions"
              >
                <q-btn
                  v-if="singleFindingField(item.finding)"
                  outline
                  no-caps
                  dense
                  color="primary"
                  class="validation-assistant__action-btn"
                  data-test="validation-assistant-finding-field"
                  @click="goToFindingField(item.finding)"
                  >{{ $t('validation_assistant_jump_to_field') }}</q-btn
                >
                <q-btn
                  v-if="findingDeepLink(item.finding)"
                  outline
                  no-caps
                  dense
                  color="primary"
                  class="validation-assistant__action-btn"
                  data-test="validation-assistant-finding-setting"
                  @click="goToFindingSetting(item.finding)"
                  >{{ $t('settings_assistant_open_setting') }}</q-btn
                >
                <q-btn
                  v-if="findingDocLink(item.finding)"
                  outline
                  no-caps
                  dense
                  color="primary"
                  class="validation-assistant__action-btn"
                  data-test="validation-assistant-finding-document"
                  @click="goToFindingDocument(item.finding)"
                  >{{ $t('open_document') }}</q-btn
                >
              </div>
              <div
                v-if="findingAdmin(item.finding)"
                class="validation-assistant__finding-admin"
                data-test="validation-assistant-finding-admin"
              >
                <p class="validation-assistant__finding-admin-title">
                  {{ $t('validation_assistant_finding_admin_title') }}
                </p>
                <p v-for="(line, lineIndex) in adminLines(item.finding)" :key="lineIndex">
                  {{ line }}
                </p>
              </div>
            </div>
            <AssistantNavRow
              v-else-if="item.type === 'nav-group'"
              :title="item.group.title"
              :summary="navSummary(item.group)"
              :reason="item.group.reason"
              :chips="item.group.chips"
              :limit="chipLimit"
              test-id="validation-assistant"
              :data-kind="item.group.kind"
              @pick="runNavChip(item.group, $event)"
            />
            <AssistantActionCard
              v-else-if="item.type === 'action'"
              data-test="validation-assistant-action-card"
              :data-kind="item.card.action.kind"
              :kicker="cardKicker(item.card.action)"
              :title="item.card.action.label"
              :reason="cardReason(item.card.action)"
              :current-value="cardCurrentValue(item.card.action)"
              :proposed-value="cardProposedValue(item.card.action)"
              test-id="validation-assistant"
            >
              <ul
                v-if="cardDetails(item.card.action).length"
                class="validation-assistant__table-list"
                data-test="validation-assistant-action-details"
              >
                <li v-for="(line, lineIndex) in cardDetails(item.card.action)" :key="lineIndex">
                  {{ line }}
                </li>
              </ul>
              <template v-if="canRunAction(item.card.action)" #actions>
                <q-btn
                  unelevated
                  no-caps
                  color="primary"
                  class="validation-assistant__action-btn"
                  :loading="item.card.status === 'running'"
                  :disable="isCardDisabled(item.card)"
                  :data-test="`validation-assistant-action-${item.card.action.kind}`"
                  @click="runAction(item.card)"
                  >{{ actionLabel(item.card.action) }}</q-btn
                >
              </template>
            </AssistantActionCard>
            </template>
            <p
              v-if="(turn.actions || []).some((card) => isHiddenForEdit(card.action))"
              class="validation-assistant__note"
              data-test="validation-assistant-read-only"
            >
              {{ changeBlockedText }}
            </p>
            <!-- CORE-6235: "what does this change do?" — before the card that applies it -->
            <ValidationAssistantExplainerCard
              collapsible
              v-for="explainer in turnView(turn).explainers"
              :key="explainer.id"
              :explainer="explainer"
              :doc-id="docId"
              :can-apply-form="canChangeFields"
              @apply="onExplainerApply"
              @apply-form="applyFormAction"
            />
            <!-- CORE-6307: everything else of the improvement answer: ONE "N more" line -->
            <div
              v-if="answerMoreCount(turn)"
              class="validation-assistant__collapsed"
              data-test="validation-assistant-answer-collapsed"
            >
              <q-btn
                flat
                no-caps
                dense
                align="left"
                :icon="turn.moreOpen ? 'expand_less' : 'expand_more'"
                class="validation-assistant__collapsed-toggle"
                :aria-expanded="turn.moreOpen ? 'true' : 'false'"
                :label="countText('validation_assistant_more_items', answerMoreCount(turn))"
                data-test="validation-assistant-answer-collapsed-toggle"
                @click="turn.moreOpen = !turn.moreOpen"
              />
              <ul
                v-if="turn.moreOpen"
                class="validation-assistant__collapsed-list"
                data-test="validation-assistant-answer-collapsed-list"
              >
                <li
                  v-for="group in collapsedGroups(turn)"
                  :key="'m-' + group.key"
                  class="validation-assistant__collapsed-item"
                  data-test="validation-assistant-answer-collapsed-item"
                  :data-kind="group.kind"
                >
                  <span class="validation-assistant__collapsed-title">{{ group.title }}</span>
                  <span v-if="group.badge" class="validation-assistant__collapsed-badge">{{
                    group.badge
                  }}</span>
                  <span v-if="group.fields.length" class="validation-assistant__collapsed-field">{{
                    group.fields.join(', ')
                  }}</span>
                  <q-btn
                    v-for="item in group.actions"
                    :key="'ma-' + item.id"
                    flat
                    no-caps
                    dense
                    size="sm"
                    color="primary"
                    class="validation-assistant__collapsed-action"
                    :loading="collapsedCard(turn, item)?.status === 'running'"
                    :disable="isCardDisabled(collapsedCard(turn, item)!)"
                    :label="collapsedActionLabel(item, group.actions.length)"
                    :data-test="`validation-assistant-answer-collapsed-action-${item.action!.kind}`"
                    @click="runAction(collapsedCard(turn, item)!)"
                  />
                </li>
              </ul>
            </div>
            <!-- CORE-6145: "shall I switch this on?" (e.g. the lookup searching by the VAT id) -->
            <SettingsAssistantSettingsActionCard
              v-for="offer in turnView(turn).settingsActions"
              :key="offer.preview_id"
              data-test="validation-assistant-settings-action"
              :data-apply-ref="offer.preview_id"
              :offer="offer"
            />
            <!-- CORE-6145: "should I create this rule?" (e.g. an IBAN read with spaces) -->
            <SettingsAssistantRulePreviewCard
              v-if="turn.rulePreview && turnView(turn).rulePreview"
              data-test="validation-assistant-rule-preview"
              :data-apply-ref="turn.rulePreview.preview_id"
              :preview="turn.rulePreview"
              :created-rule-id="turn.ruleCreatedId || null"
              @created="turn.ruleCreatedId = $event?.rule_id || $event || 'created'"
            />
          </div>
        </template>
      </AssistantBubble>

      <AssistantStreamingBubble
        v-if="isStreaming"
        :text="streamingText"
