// At most four chips; the setup chip only for users who may see the setup.
const MAX_CHIPS = 4;

// API finding area → translation key.
const FINDING_AREA_KEYS: Record<string, string> = {
  field: 'validation_assistant_area_field',
  extraction: 'validation_assistant_area_extraction',
