 */
const EMPTY_BOARD: ValidationBlockers = { blocking: [], hidden: [], tables: [], total: 0 };

// CORE-6161: kinds that only work where the form is on the page.
const FORM_ONLY_ACTION_KINDS = new Set(['go_to_table_cell', 'next_open_field']);

const SCREEN_QUESTIONS: Record<string, string[]> = {
  po_match: ['validation_assistant_question_po_match'],
  accounting: ['validation_assistant_question_accounting'],
