// Several plain lines read as a wall of text; show them as a list.
function asBulletList(text: string): string {
  const lines = text.split('\n').map((line) => line.trim()).filter(Boolean);
  if (lines.length < 2 || !text.includes('\n')) return text;
  if (lines.some((line) => /^([-*+]|\d+[.)]|#|>|\||```)/.test(line))) return text;
  return lines.map((line) => `- ${line}`).join('\n');
}

const SUGGESTIONS_OPEN_KEY = 'docbits:validation-assistant:suggestions-open';

function readSuggestionsOpen(): boolean {
  try {
    return localStorage.getItem(SUGGESTIONS_OPEN_KEY) !== 'false';
  } catch {
    return true;
  }
}

interface ConversationState {
  turns: Turn[];
  conversationId: string;
}

/** CORE-6307 — the capped improvement answer of one turn (doc2-api answer_cap). */
interface CappedAnswer {
  collapsed: CollapsedItem[];
  moreCount: number;
}

interface ChatError {
  traceId: string;
  retryable?: boolean;
  kind?: 'rate_limited' | 'forbidden' | 'unavailable' | 'timeout';
}

function newConversationId(): string {
  return typeof crypto !== 'undefined' && 'randomUUID' in crypto
    ? crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

export default defineComponent({
  name: 'ValidationAssistantPanel',
  components: {
    Icon,
    AssistantNavRow,
    SettingsAssistantRulePreviewCard,
    SettingsAssistantSettingsActionCard,
    ValidationAssistantExplainerCard,
    ValidationAssistantAiTagPreviewCard,
    AssistantShell,
    AssistantResizeGrip,
    AssistantHeader,
    AssistantMessageList,
    AssistantBubble,
    AssistantStreamingBubble,
    AssistantErrorNotice,
    AssistantExampleChips,
    AssistantComposer,
    AssistantActionCard,
    AssistantAppliedChangeLine,
  },
  props: {
    docId: {
      type: String,
      default: '',
    },
    /**
     * CORE-6161 popout: the board handed over by the validation screen. A
     * separate window shares no Pinia state with its opener, so it cannot
     * build the form-builder model itself; the prop wins when supplied.
     */
    blockers: {
      type: Object as () => ValidationBlockers | null,
      default: null,
    },
    /** CORE-6161: where the panel lives; off the validation screen there is no form to change. */
    screen: {
      type: String as PropType<AssistantScreen>,
      default: 'validation',
    },
    /** CORE-6454: the document has an AI table; only then the symptom chips show. */
    hasAiTable: {
      type: Boolean,
      default: false,
    },
    /** True in the pop-out window: board + chat, never a form change. */
    windowMode: {
      type: Boolean,
      default: false,
    },
    /**
     * CORE-6161 popout: the docked sidebar after the chat moved to the window.
     * Board + jumps stay live; the chat/composer are hidden behind a hint.
     */
    compact: {
      type: Boolean,
      default: false,
    },
    /** True when the window was opened standalone and has no live opener. */
    orphaned: {
      type: Boolean,
      default: false,
    },
    // The screen's isReadOnly: form-changing actions are disabled.
    readOnly: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['close', 'pop-out', 'conversation-change', 'open-validation'],
  setup() {
    const { blockers: liveBlockers } = useValidationBlockers();
    const { org_based_settings } = storeToRefs(useSettingStore());
    const tolgee = useTolgee(['language']);
    return { liveBlockers, org_based_settings, tolgee };
  },
  data() {
    return {
      suggestionsOpen: readSuggestionsOpen(),
      chipLimit: CHIP_LIMIT,
      expandedChips: {} as Record<string, boolean>,
      turns: [] as Turn[],
      capabilities: null as AssistantCapabilities | null,
      draft: '',
      isStreaming: false,
      streamingText: '',
      error: null as ChatError | null,
      abort: null as AbortController | null,
      lastHistory: null as AssistantTurn[] | null,
      conversationId: newConversationId(),
      sessionChanges: [] as SessionChange[],
      lastFocusedField: null as string | null,
      maxQuestionLength: 2000,
      windowWidth: typeof window !== 'undefined' ? window.innerWidth : 1440,
      highlightTimer: null as ReturnType<typeof setTimeout> | null,
      // CORE-6249: improvements of the open document, cached per document + language
      improvements: [] as Explainer[],
      improvementsAbort: null as AbortController | null,
      // CORE-6307: the collapsed "N more problems" line
      problemsOpen: false,
      boardMoreOpen: false,
      diagnosing: false,
      // CORE-6161 popout: undo the window action relay on unmount.
      disposeWindowRelay: null as (() => void) | null,
    };
  },
  watch: {
    turns: {
      deep: true,
      handler() {
        this.emitConversationChange();
      },
    },
    isStreaming(streaming: boolean) {
      if (!streaming) this.emitConversationChange();
    },
    docId() {
      this.resetConversation();
      this.importConversation(loadConversation(this.docId) as ConversationState | null);
      this.capabilities = null;
      this.sessionChanges = [];
      this.lastFocusedField = null;
      void this.loadImprovements();
    },
    orgEnabled() {
      void this.loadImprovements();
    },
    appLanguage() {
      void this.loadImprovements();
    },
  },
  mounted() {
    window.addEventListener('resize', this.onWindowResize);
    // CORE-6161 popout: in the window, the panel's action events go to the
    // opener's document, which already listens; the reply comes back bridged.
    if (this.windowMode) {
      this.disposeWindowRelay = installWindowActionRelay();
    }
    this.importConversation(loadConversation(this.docId) as ConversationState | null);
    void this.loadImprovements();
  },
  beforeUnmount() {
    this.abort?.abort();
    this.improvementsAbort?.abort();
    if (this.highlightTimer) clearTimeout(this.highlightTimer);
    this.disposeWindowRelay?.();
    window.removeEventListener('resize', this.onWindowResize);
  },
  computed: {
    boardFieldNames(): string[] {
      return [...this.board.blocking, ...this.board.hidden].map((blocker) => blocker.field_name);
    },
    /** CORE-6161 popout: the board handed over by the screen wins, else the live one. */
    board(): ValidationBlockers {
      if (!this.onValidationScreen) return EMPTY_BOARD;
      return this.blockers ?? this.liveBlockers;
    },
    onValidationScreen(): boolean {
      return this.screen === 'validation';
    },
    /** The popup never changes the form, so it behaves like a read-only screen. */
    effectiveReadOnly(): boolean {
      return this.readOnly || this.windowMode || !this.onValidationScreen;
    },
    appLanguage(): string {
      return this.currentLanguage();
    },
    // Improvements the user has not asked about yet (an asked one is a full card in the chat).
    visibleImprovements(): Explainer[] {
      const asked = new Set<string>();
      for (const turn of this.turns) {
        for (const explainer of turn.explainers || []) {
          asked.add(explainer.id);
          asked.add(explainer.offer_id);
        }
        for (const item of turn.collapsed || []) {
          asked.add(item.id);
          if (item.offer_id) asked.add(item.offer_id);
        }
      }
      return this.improvements.filter(
        (item) =>
          !isBlockerDecision(item) && !asked.has(item.id) && !asked.has(item.offer_id),
      );
    },
    // CORE-6307: less is more -- offers first (server order = impact), then the
    // decisions that have a safe change; at most MAX_SUGGESTIONS (selectSuggestions)
    suggestions(): Explainer[] {
      return selectSuggestions([...this.visibleImprovements, ...this.visibleProblems]).shown;
    },
    // CORE-6307: deferred / elsewhere / still checked -- one expandable line
    collapsedProblems(): Explainer[] {
      return this.visibleProblems.filter((item) => !hasSafeChange(item));
    },
    collapsedCount(): number {
      // the server explains a few blockers and summarises the rest as "more"
      const more = this.visibleProblems.reduce(
        (sum, item) => sum + (item.more?.count ?? 0),
        0,
      );
      return this.collapsedProblems.length + (this.collapsedProblems.length ? more : 0);
    },
    // CORE-6249 v2: the blocker decisions of the open document, not yet asked about
    visibleProblems(): Explainer[] {
      const asked = new Set<string>();
      for (const turn of this.turns) {
        for (const explainer of turn.explainers || []) {
          asked.add(explainer.id);
          asked.add(explainer.offer_id);
        }
        for (const item of turn.collapsed || []) {
          asked.add(item.id);
          if (item.offer_id) asked.add(item.offer_id);
        }
      }
      return this.improvements.filter(
        (item) =>
          isBlockerDecision(item) && !asked.has(item.id) && !asked.has(item.offer_id),
      );
    },
    serverBlockerCount(): number {
      const cards = [
        ...this.improvements,
        ...this.turns.flatMap((turn) => turn.explainers || []),
      ];
      return new Set(
        cards.filter(isBlockerDecision).map((item) => item.offer_id),
      ).size;
    },
    orgEnabled(): boolean {
      return toBoolPreference(
        this.org_based_settings?.[validation_assistant_enabled_setting],
      );
    },
    chatEnabled(): boolean {
      return this.orgEnabled && !!this.docId;
    },
    // Until the API says otherwise: change only on an editable screen, never see the setup.
    effectiveCapabilities(): AssistantCapabilities {
      const base = this.capabilities ?? {
        tier: this.effectiveReadOnly ? 'viewer' : 'editor',
        can_change_fields: !this.effectiveReadOnly,
        can_see_setup: false,
      };
      // The window never changes the form, whatever tier the server reports.
      if (this.windowMode) return { ...base, can_change_fields: false };
      return base;
    },
    canChangeFields(): boolean {
      return !this.effectiveReadOnly && this.effectiveCapabilities.can_change_fields;
    },
    canSeeSetup(): boolean {
      return this.effectiveCapabilities.can_see_setup;
    },
    changeBlockedText(): string {
      return this.effectiveReadOnly
        ? this.$t('validation_assistant_read_only_hint')
        : this.$t('validation_assistant_viewer_hint');
    },
    // Rotates with the situation: open fields, own changes, nothing blocking; setup last for admins.
    questionChips(): AssistantExampleChip[] {
      const { blocking, total } = this.board;
      const keys: string[] = [...(SCREEN_QUESTIONS[this.screen] || []), QUESTION_MISSING, QUESTION_IMPROVE];
      if (blocking.length) keys.push(QUESTION_NEXT_FIELD);
      if (this.sessionChanges.length) keys.push(QUESTION_MY_CHANGES);
      if (!total) keys.push(QUESTION_CAN_EXPORT);
      if (this.effectiveCapabilities.tier !== 'viewer') keys.push(QUESTION_VALUE_ORIGIN);
      keys.push(QUESTION_VALUE_CHANGES, QUESTION_EXTRACTION, QUESTION_RED);
      const picked = [...new Set(keys)].slice(0, this.canSeeSetup ? MAX_CHIPS - 1 : MAX_CHIPS);
      if (this.canSeeSetup) picked.push(QUESTION_AI_SETUP);
      return picked.map((key) => ({
        key,
        label: String(this.$t(key)),
        disabled: key !== QUESTION_NEXT_FIELD && !this.chatEnabled,
      }));
    },
    diagnosisChipsVisible(): boolean {
      return this.hasAiTable && this.chatEnabled && this.onValidationScreen && !this.orphaned;
    },
    symptomChips(): AssistantExampleChip[] {
      return SYMPTOM_CHIPS.map(({ key }) => ({
        key,
        label: String(this.$t(key)),
        dataTest: 'validation-assistant-diagnosis-chip',
      }));
    },
    // CORE-6454: the improvement teasers count too; blockers beyond the cap become one line
    boardCap(): {
      blocking: ValidationBlockers['blocking'];
      hidden: ValidationBlockers['hidden'];
      tables: TableGroup[];
      rest: BoardOverflowItem[];
    } {
      let room = Math.max(0, MAX_VISIBLE_CARDS - this.suggestions.length);
      const rest: BoardOverflowItem[] = [];
      function take<T>(list: T[], overflow: (item: T) => BoardOverflowItem): T[] {
        const shown = list.slice(0, room);
        room -= shown.length;
        rest.push(...list.slice(shown.length).map(overflow));
        return shown;
      }
      const blocking = take<FieldBlocker>(this.board.blocking, (b: FieldBlocker) => ({
        key: 'b-' + b.field_name,
        title: b.label,
        badge: this.kindLabel(b.kind),
      }));
      const hidden = take<FieldBlocker>(this.board.hidden, (b: FieldBlocker) => ({
        key: 'h-' + b.field_name,
        title: b.label,
        badge: String(this.$t('validation_assistant_kind_hidden')),
      }));
      const tables = take<TableGroup>(this.tableGroups, (table: TableGroup) => ({
        key: 't-' + table.table_name,
        title: String(this.$t('validation_assistant_table_title')),
        badge: String(this.$t('validation_assistant_table_count', { count: table.items.length })),
      }));
      return { blocking, hidden, tables, rest };
    },
    openFieldNames(): string[] {
      return this.board.blocking.map((blocker) => blocker.field_name);
    },
    minWidth(): number {
      return VALIDATION_ASSISTANT_MIN_WIDTH;
    },
    maxWidth(): number {
      return validationAssistantMaxWidth(this.windowWidth);
    },
    // Without a dragged width the sidebar is 25vw.
    gripWidth(): number {
      return validationAssistantWidth.width ?? Math.round(this.windowWidth * 0.25);
    },
    // CORE-6161 popout: the window has room for a two-column layout — board on
    // the left, chat on the right — instead of the cramped single sidebar flow.
    wide(): boolean {
      return this.windowMode && this.windowWidth >= 1100;
    },
    errorText(): string {
      if (!this.error) return '';
      switch (this.error.kind) {
        case 'rate_limited':
          return this.$t('settings_assistant_rate_limited');
        case 'forbidden':
          return this.$t('validation_assistant_forbidden');
        case 'unavailable':
          return this.$t('settings_assistant_unavailable_retry');
        case 'timeout':
          return this.$t('settings_assistant_timeout');
        default:
          return this.$t('settings_assistant_error');
      }
    },
    summary(): string {
      const { blocking, hidden, tables } = this.board;
      // Server-only checks can find blockers the form's field flags missed.
      // Moving a teaser into chat must not turn those known blockers into "none".
      if (this.serverBlockerCount > blocking.length + hidden.length + tables.length) {
        return this.countText('validation_assistant_problems_found', this.serverBlockerCount);
      }
      if (!blocking.length && !hidden.length && !tables.length) {
        return this.$t('validation_assistant_summary_none');
      }
      const parts: string[] = [];
      if (blocking.length) {
        parts.push(this.countText('validation_assistant_summary_fields', blocking.length));
      }
      if (hidden.length) {
        parts.push(this.countText('validation_assistant_summary_hidden', hidden.length));
      }
      if (tables.length) {
        parts.push(this.countText('validation_assistant_summary_tables', tables.length));
      }
      return parts.join(' ');
    },
    tableGroups(): TableGroup[] {
      const groups: { table_name: string; items: TableBlocker[] }[] = [];
      for (const item of this.board.tables) {
        let group = groups.find((g) => g.table_name === item.table_name);
        if (!group) {
          group = { table_name: item.table_name, items: [] };
          groups.push(group);
        }
        group.items.push(item);
      }
      return groups;
    },
  },
  methods: {
    countText(key: string, count: number): string {
      return this.$t(`${key}_${count === 1 ? 'one' : 'other'}`, { count });
    },
    kindLabel(kind: BlockerKind): string {
      return this.$t(`validation_assistant_kind_${kind}`);
    },
    tableItemText(item: TableBlocker): string {
      const where: string[] = [];
      if (item.row_index !== null) {
        where.push(
          this.$t('validation_assistant_table_row', { row: item.row_index + 1 }),
        );
      }
      if (item.column) {
        where.push(item.column);
      }
      return where.length ? `${where.join(' · ')}: ${item.reason}` : item.reason;
    },
    jumpToField(field_name: string) {
      this.lastFocusedField = field_name;
      // off the validation screen the field is not on the page: open it there
      if (!this.onValidationScreen) {
        this.$emit('open-validation', field_name);
        return;
      }
      document.dispatchEvent(
        new CustomEvent(FOCUS_BLOCKED_FIELD_EVENT, { detail: { field_name } }),
      );
    },
    jumpToTable(table_name: string) {
      document.dispatchEvent(
        new CustomEvent(FOCUS_BLOCKED_TABLE_EVENT, { detail: { table_name } }),
      );
    },

    changesForm(action: AssistantAction): boolean {
      return !!actionHandler(action.kind)?.changesForm;
    },
    actionLabel(action: AssistantAction): string {
      const handler = actionHandler(action.kind);
      return handler ? this.$t(handler.labelKey) : '';
    },
    cellText(action: AssistantAction): string {
      const row = this.$t('validation_assistant_table_row', { row: (action.row_index ?? 0) + 1 });
      return `${row} · ${action.column_label || action.column || ''}`;
    },
    cardKicker(action: AssistantAction): string {
      switch (action.kind) {
        case 'go_to_table_cell':
        case 'set_table_cell':
          return this.cellText(action);
        case 'suggest_rule':
          return this.$t('validation_assistant_rule_suggestion');
        case 'reclassify':
          return this.$t('document_type');
        case 'create_support_ticket':
          return this.$t('support_ticket');
        case 'create_task':
          return this.$t('task');
        default:
          return action.section || '';
      }
    },
    cardReason(action: AssistantAction): string {
      if (action.kind === 'suggest_rule') {
        return action.target_label
          ? `${action.target_label}: ${action.description || ''}`
          : action.description || '';
      }
      if (action.kind === 'create_support_ticket') return action.reason || action.subject || '';
      if (action.kind === 'create_task') return action.reason || action.title || '';
      if (action.kind === 'add_table_row') return action.reason || action.display || '';
      return action.reason || '';
    },
    cardCurrentValue(action: AssistantAction): string | null {
      switch (action.kind) {
        case 'set_value':
        case 'set_table_cell':
        case 'use_po':
        case 'apply_lookup_candidate':
          return action.current_display || this.$t('validation_assistant_action_empty');
        default:
          return null;
      }
    },
    cardProposedValue(action: AssistantAction): string | null {
      switch (action.kind) {
        case 'set_value':
        case 'set_table_cell':
        case 'use_po':
          return action.display_value || action.value || '';
        case 'apply_lookup_candidate':
          return action.candidate_display || '';
        default:
          return null;
      }
    },
    cardDetails(action: AssistantAction): string[] {
      switch (action.kind) {
        case 'apply_lookup_candidate':
          return (action.fills || []).map((fill) => `${fill.label}: ${fill.display || '–'}`);
        case 'bulk_confirm':
          return (action.fields || []).map((field) => field.label);
        case 'reclassify':
          return [this.$t('validation_assistant_reclassify_to', { type: action.doc_type_label })];
        case 'add_table_row':
          return action.display
            ? []
            : Object.entries(action.preset || {}).map(([column, value]) => `${column}: ${value}`);
        default:
          return [];
      }
    },
    canRunAction(action: AssistantAction): boolean {
      return canRunAssistantAction(action.kind, this.effectiveCapabilities, this.effectiveReadOnly);
    },
    /**
     * CORE-6161 popout: in the window the form-changing cards are left out
     * entirely (their buttons are already gated, but an inert card still reads
     * as "you can do this here"). The read-only note below explains where to go.
     */
    windowSafeActions(cards: ActionCardState[] | undefined): ActionCardState[] {
      if (!this.windowMode && this.onValidationScreen) return cards || [];
      return (cards || []).filter(
        (card) =>
          !WINDOW_BLOCKED_ACTION_KINDS.has(card.action.kind) &&
          (this.onValidationScreen || !FORM_ONLY_ACTION_KINDS.has(card.action.kind)),
      );
    },
    // An editor action without its button: say why under the cards.
    isHiddenForEdit(action: AssistantAction): boolean {
      return actionHandler(action.kind)?.minTier === 'editor' && !this.canRunAction(action);
    },
    isCardDisabled(card: ActionCardState): boolean {
      if (card.status === 'running') return true;
      if (!this.canRunAction(card.action)) return true;
      return this.changesForm(card.action) && card.status === 'done';
    },
    actionContext(): ActionContext {
      return {
        router: this.$router,
        openFields: this.openFieldNames,
        lastField: this.lastFocusedField,
      };
    },

    findingVariant(finding: AssistantFinding): 'default' | 'warning' | 'danger' {
      if (finding.severity === 'error') return 'danger';
      return finding.severity === 'warning' ? 'warning' : 'default';
    },
    severityVariant(severity: AssistantFinding['severity']): 'default' | 'warning' | 'danger' {
      if (severity === 'error') return 'danger';
      return severity === 'warning' ? 'warning' : 'default';
    },
    // CORE-6161: findings, jumps and other cards of one answer as one sorted list.
    sortedTurnItems(turn: Turn): TurnItem[] {
      const findings = turn.findings || [];
      const { groups, solo } = splitFindings(findings);
      // board cells stay: the board only jumps to the table, the chip to the cell
      const covered = { fields: new Set<string>(this.boardFieldNames), cells: new Set<string>() };
      for (const finding of findings) {
        for (const name of findingFieldNames(finding)) covered.fields.add(name);
      }
      const cards = this.windowSafeActions(turn.actions);
      const navGroups = groupNavCards(
        cards.filter((card) => NAV_KINDS.has(card.action.kind)),
        covered,
        {
          fieldJump: String(this.$t('validation_assistant_jump_to_field')),
          row: (row) => String(this.$t('validation_assistant_table_row', { row })),
        },
      );
      const items: TurnItem[] = [
        ...groups.map((group) => ({ type: 'finding-group' as const, key: 'fg-' + group.key, group })),
        ...solo.map((finding) => ({ type: 'finding' as const, key: 'f-' + finding.id, finding })),
        ...navGroups.map((group) => ({ type: 'nav-group' as const, key: 'n-' + group.key, group })),
        ...cards
          .filter((card) => !NAV_KINDS.has(card.action.kind))
          .map((card) => ({ type: 'action' as const, key: 'a-' + card.action.id, card })),
      ];
      return sortTurnItems(items, new Set<string>(this.boardFieldNames));
    },
    // CORE-6454: every big card of one answer together, at most MAX_VISIBLE_CARDS; nav rows are not cards
    turnView(turn: Turn): TurnView {
      const items = this.sortedTurnItems(turn);
      const explainers = this.answerExplainers(turn);
      const settingsActions = turn.settingsActions || [];
      const rulePreview = turn.rulePreview && turn.moreCount === undefined ? turn.rulePreview : null;
      const cards: CappedCard[] = [
        ...(this.isDiagnosisVisible(turn) || turn.aiTagPreview
          ? [{ slot: 'diagnosis' as const, kind: 'diagnosis' as const }]
          : []),
        ...settingsActions.map((offer) => ({ slot: 'settings_action' as const, kind: 'settings' as const, offer })),
        ...(rulePreview ? [{ slot: 'rule_preview' as const, kind: 'rule' as const, preview: rulePreview }] : []),
        ...items
          .filter((item) => item.type !== 'nav-group')
          .map((item) => ({
            slot: (item.type === 'action' ? 'action' : 'finding') as CardSlot,
            kind: 'item' as const,
            item,
          })),
        ...explainers.map((explainer) => ({ slot: 'explainer' as const, kind: 'explainer' as const, explainer })),
      ];
      const { shown, rest } = capCards(cards);
      if (!rest.length) {
        return { items, explainers, settingsActions, rulePreview: !!rulePreview, overflow: [] };
      }
      const kept = (match: (card: CappedCard) => boolean) => shown.some(match);
      return {
        items: items.filter((item) => item.type === 'nav-group' || kept((c) => c.kind === 'item' && c.item === item)),
        explainers: explainers.filter((e) => kept((c) => c.kind === 'explainer' && c.explainer === e)),
        settingsActions: settingsActions.filter((o) => kept((c) => c.kind === 'settings' && c.offer === o)),
        rulePreview: !!rulePreview && kept((c) => c.kind === 'rule'),
        overflow: rest.map((card) => this.overflowLine(card)).filter((line): line is CollapsedItem => !!line),
      };
    },
    overflowLine(card: CappedCard): CollapsedItem | null {
      const line = {
        offer_id: null,
        field_label: null,
        operation: null,
        pending: false,
        area: null,
        action: null,
      };
      switch (card.kind) {
        case 'settings':
          return {
            ...line,
            kind: 'settings_action',
            id: card.offer.preview_id,
            title: card.offer.changes[0]?.title || String(this.$t('validation_assistant_diagnosis_setting_change')),
          };
        case 'rule':
          return {
            ...line,
            kind: 'rule_preview',
            id: card.preview.preview_id,
            title: card.preview.rule?.display_name || card.preview.sentence,
          };
        case 'explainer':
          return {
            ...line,
            kind: 'explainer',
            id: card.explainer.id,
            offer_id: card.explainer.offer_id,
            title: card.explainer.title,
            field_label: card.explainer.field_label || null,
            operation: card.explainer.decision?.operation ?? null,
            pending: !!card.explainer.pending,
          };
        case 'item': {
          const item = card.item;
          if (item.type === 'action') {
            return {
              ...line,
              kind: 'action',
              id: item.card.action.id,
              title: item.card.action.label,
              action: item.card.action,
            };
          }
          if (item.type === 'finding') {
            return {
              ...line,
              kind: 'finding',
              id: item.finding.id,
              title: item.finding.title,
              field_label: item.finding.label || null,
              area: item.finding.area || null,
            };
          }
          if (item.type === 'finding-group') {
            return { ...line, kind: 'finding', id: item.key, title: item.group.title, area: item.group.area || null };
          }
          return null;
        }
        default:
          return null;
      }
    },
    navSummary(group: NavGroup): string {
      if (group.kind === 'cell') {
        return String(
          this.$t('validation_assistant_nav_rows', {
            rows: rowRangeText(group.chips.map((chip) => Number(chip.key))),
          }),
        );
      }
      return group.chips.length > 1 ? this.countText('validation_assistant_nav_fields', group.chips.length) : '';
    },
    runNavChip(group: NavGroup, key: string) {
      const chip = group.chips.find((entry) => entry.key === key);
      if (!chip) return;
      if (!this.onValidationScreen && chip.card.action.kind === 'go_to_field') {
        this.jumpToField(chip.card.action.field);
        return;
      }
      void this.runAction(chip.card as ActionCardState);
    },
    findingChips(finding: AssistantFinding): { key: string; label: string }[] {
      return (finding.fields || []).map((entry) => ({ key: entry.name, label: entry.label || entry.name }));
    },
    visibleFindingChips(finding: AssistantFinding): { key: string; label: string }[] {
      const chips = this.findingChips(finding);
      return this.expandedChips[finding.id] ? chips : chips.slice(0, CHIP_LIMIT);
    },
    hiddenFindingChips(finding: AssistantFinding): number {
      return this.findingChips(finding).length - this.visibleFindingChips(finding).length;
    },
    // A finding about several fields jumps through its chips, not one button.
    singleFindingField(finding: AssistantFinding): boolean {
      return !!finding.field && this.findingChips(finding).length <= 1;
    },
    /**
     * CORE-6161: "2 master data records match" — the model says the count in
     * the message; a structured candidates field wins when the API sends one.
     */
    findingCandidates(finding: AssistantFinding): number | null {
      const structured = (finding as unknown as { candidates?: unknown }).candidates;
      if (typeof structured === 'number' && structured > 0) return structured;
      // The model puts the count in the message ("2 master data records match" /
      // "2 Stammdatensätze stimmen überein"); a structured field wins if added.
      const match = /(\d+)\s+(?:master data records|candidates?|Kandidaten?|Stammdatensätze|Datensätze)/i.exec(
        finding.message || '',
      );
      return match ? Number(match[1]) : null;
    },
    areaLabel(area: string): string {
      return this.$t(
        Object.prototype.hasOwnProperty.call(FINDING_AREA_KEYS, area)
          ? FINDING_AREA_KEYS[area]
          : 'validation_assistant_area_other',
      );
    },
    findingAdmin(finding: AssistantFinding) {
      return this.canSeeSetup ? finding.admin ?? null : null;
    },
    adminLines(finding: AssistantFinding): string[] {
      const admin = this.findingAdmin(finding);
      if (!admin) return [];
      const lines: string[] = [];
      if (admin.detail) lines.push(admin.detail);
      if (admin.script_label) {
        lines.push(this.$t('validation_assistant_finding_script', { name: admin.script_label }));
      }
      if (admin.trigger) {
        lines.push(this.$t('validation_assistant_finding_trigger', { trigger: admin.trigger }));
      }
      if (admin.rule_label) {
        lines.push(this.$t('validation_assistant_finding_rule', { name: admin.rule_label }));
      }
      const setting = admin.setting_label || admin.setting_key;
      if (setting) {
        lines.push(this.$t('validation_assistant_finding_setting', { name: setting }));
      }
      return lines;
    },
    findingDocLink(finding: AssistantFinding): string | null {
      return isResolvableAppPath(this.$router, finding.path) ? finding.path : null;
    },
    async goToFindingDocument(finding: AssistantFinding) {
      const path = this.findingDocLink(finding);
      if (path) await this.$router.push(path);
    },
    findingDeepLink(finding: AssistantFinding): string | null {
      const path = this.findingAdmin(finding)?.deep_link;
      return isResolvableAppPath(this.$router, path) ? path : null;
    },
    async goToFindingSetting(finding: AssistantFinding) {
      const path = this.findingDeepLink(finding);
      if (path) await this.$router.push(path);
    },
    goToFindingField(finding: AssistantFinding) {
      if (!finding.field) return;
      if (!this.onValidationScreen) {
        this.jumpToField(finding.field);
        return;
      }
      void actionHandler('go_to_field')?.run({
        id: `finding:${finding.id}`,
        kind: 'go_to_field',
        field: finding.field,
        label: finding.label || finding.title,
      });
    },
    reasonText(reason?: string): string {
      return this.$t(`validation_assistant_action_reason_${reason || 'failed'}`);
    },
    pushNotice(text: string) {
      this.turns.push({ role: 'system', text });
      this.scrollToBottom();
    },
    sessionChangesOf(action: AssistantAction, result: FieldActionResult): SessionChange[] {
      const drafts: SessionChangeDraft[] = Array.isArray(result.changes) ? result.changes : [];
      const now = new Date();
      const changes = drafts
        .filter((draft) => draft && typeof draft.field === 'string' && draft.field)
        .map((draft) => toSessionChange(draft, now));
      if (changes.length || action.kind !== 'set_value') return changes;
      return [
        toSessionChange(
          { field: action.field, label: action.label, from: action.current_display, to: action.display_value, kind: 'set_value' },
          now,
        ),
      ];
    },
    async runAction(card: ActionCardState) {
      const handler = actionHandler(card.action.kind);
      if (!handler || this.isCardDisabled(card)) return;
      card.status = 'running';
      let result: FieldActionResult;
      try {
        result = await handler.run(card.action, this.actionContext());
      } catch {
        result = { ok: false, reason: 'failed' };
      }
      if (!result.ok) {
        card.status = 'idle';
        if (handler.changesForm) {
          this.pushChange(card, result, false);
        } else {
          this.pushNotice(`${card.action.label}: ${this.reasonText(result.reason)}`);
        }
        return;
      }
      if (card.action.kind === 'next_open_field' && typeof result.applied === 'string') {
        this.lastFocusedField = result.applied;
      }
      if (!handler.changesForm || result.undoable === false) {
        card.status = 'idle';
        const notice = result.notice || this.noticeKey(card.action);
        if (notice) this.pushNotice(this.$t(notice, { field: card.action.label }));
        return;
      }
      card.status = 'done';
      this.pushChange(card, result, !!handler.undo);
    },
    noticeKey(action: AssistantAction): string {
      if (action.kind === 'reclassify') return 'validation_assistant_action_reclassify_open';
      return '';
    },
    pushChange(card: ActionCardState, result: FieldActionResult, canUndo: boolean) {
      const sessionChanges = result.ok ? this.sessionChangesOf(card.action, result) : [];
      this.sessionChanges = capSessionChanges([...this.sessionChanges, ...sessionChanges]);
      this.turns.push({
        role: 'system',
        text: result.ok
          ? this.doneText(card.action, result)
          : `${card.action.label}: ${this.reasonText(result.reason)}`,
        change: {
          action: card.action,
          card,
          result,
          canUndo: result.ok && canUndo,
          undone: false,
          undoing: false,
          failed: !result.ok,
          sessionChanges,
        },
      });
      this.scrollToBottom();
    },
    doneText(action: AssistantAction, result?: FieldActionResult): string {
      const value = action.display_value || action.value || '';
      switch (action.kind) {
        case 'set_value':
        case 'use_po':
          return this.$t('validation_assistant_action_set_done', { field: action.label, value });
        case 'set_table_cell':
          return this.$t('validation_assistant_action_cell_done', {
            cell: this.cellText(action),
            value,
          });
        case 'add_table_row':
          return this.$t('validation_assistant_action_row_done', {
            row: action.display || action.label,
          });
        case 'apply_lookup_candidate':
        case 'rerun_lookup':
          return this.$t('validation_assistant_action_lookup_done', {
            field: action.label,
            count: result?.changes?.length ?? 0,
          });
        case 'bulk_confirm': {
          const summary = (result?.applied || {}) as { confirmed?: number; total?: number };
          return this.$t('validation_assistant_action_bulk_done', {
            count: summary.confirmed ?? 0,
            total: summary.total ?? (action.fields || []).length,
          });
        }
        default:
          return this.$t('validation_assistant_action_confirm_done', { field: action.label });
      }
    },
    async undoChange(change: AppliedChange) {
      const handler = actionHandler(change.action.kind);
      if (!handler?.undo || change.undone || change.undoing || !this.canRunAction(change.action)) return;
      change.undoing = true;
      let result: FieldActionResult;
      try {
        result = await handler.undo(change.action, change.result);
      } catch {
        result = { ok: false, reason: 'failed' };
      }
      change.undoing = false;
      if (result.ok) {
        change.undone = true;
        change.card.status = 'idle';
        this.sessionChanges = capSessionChanges([
          ...this.sessionChanges,
          ...undoSessionChanges(change.sessionChanges),
        ]);
        return;
      }
      this.turns.push({
        role: 'system',
        text: `${change.action.label}: ${this.reasonText(result.reason)}`,
        change: {
          action: change.action,
          card: change.card,
          result,
          canUndo: false,
          undone: false,
          undoing: false,
          failed: true,
          sessionChanges: [],
        },
      });
      this.scrollToBottom();
    },
    async goToNextOpenField() {
      const handler = actionHandler('next_open_field');
      if (!handler) return;
      const result = await handler.run(
        { id: 'chip:next_open_field', kind: 'next_open_field', field: '', label: '' },
        this.actionContext(),
      );
      if (result.ok && typeof result.applied === 'string') {
        this.lastFocusedField = result.applied;
        const blocker = this.board.blocking.find((b) => b.field_name === result.applied);
        this.pushNotice(
          this.$t('validation_assistant_next_field_done', { field: blocker?.label || result.applied }),
        );
        return;
      }
      this.pushNotice(this.$t('validation_assistant_next_field_none'));
    },
    pickChip(chip: AssistantExampleChip) {
      if (chip.key === QUESTION_NEXT_FIELD) {
        void this.goToNextOpenField();
        return;
      }
      if (chip.key === QUESTION_IMPROVE) {
        void this.askImprove();
        return;
      }
      void this.ask(chip.key);
    },
    // The same question for the chip and the teaser button: the full chat flow, with audio.
    async askImprove() {
      if (!this.chatEnabled || this.isStreaming) return;
      await this.sendText(improveQuestion(this.currentLanguage()));
    },
    watchImprovements() {
      void this.askImprove();
    },
    // a pending decision shows "being checked", never a recommendation
    problemBadge(item: Explainer): string {
      const d = item.decision;
      if (!d) return '';
      if (item.pending) return String(this.$t('validation_assistant_decision_pending'));
      return String(this.$t(`validation_assistant_decision_op_${d.operation}`));
    },
    // CORE-6307: a capped answer shows at most MAX_SUGGESTIONS cards (the server
    // already capped it; the same rule again so no client ever shows more)
    answerExplainers(turn: Turn): Explainer[] {
      const items = turn.explainers || [];
      return turn.moreCount === undefined ? items : selectSuggestions(items).shown;
    },
    answerCollapsed(turn: Turn): CollapsedItem[] {
      const overflow = this.turnView(turn).overflow;
      if (turn.moreCount === undefined) return overflow;
      const extra: CollapsedItem[] = selectSuggestions(turn.explainers || []).rest.map(
        (item) => ({
          kind: 'explainer',
          id: item.id,
          offer_id: item.offer_id,
          title: item.title,
          field_label: item.field_label || null,
          operation: item.decision?.operation ?? null,
          pending: !!item.pending,
          area: null,
          action: null,
        }),
      );
      return [...extra, ...(turn.collapsed || []), ...overflow];
    },
    answerMoreCount(turn: Turn): number {
      const overflow = this.turnView(turn).overflow.length;
      if (turn.moreCount === undefined) return overflow;
      const extra = selectSuggestions(turn.explainers || []).rest.length;
      return turn.moreCount + extra + overflow;
    },
    collapsedCard(turn: Turn, item: CollapsedItem): ActionCardState | null {
      const known = turn.collapsedCards?.[item.id];
      if (known) return known;
      // a card the 7-card cap moved here keeps its own state
      if (item.kind !== 'action') return null;
      return (turn.actions || []).find((card) => card.action.id === item.id) ?? null;
    },
    // One row per kind of problem: fields are listed together, jumps sit side by side.
    collapsedGroups(turn: Turn): {
      key: string;
      kind: CollapsedItem['kind'];
      title: string;
      badge: string;
      fields: string[];
      actions: CollapsedItem[];
    }[] {
      const groups = new Map<string, ReturnType<typeof this.collapsedGroups>[number]>();
      for (const item of this.answerCollapsed(turn)) {
        const badge = this.collapsedBadge(item);
        const key = `${item.kind}|${item.title}|${badge}`;
        let group = groups.get(key);
        if (!group) {
          group = { key, kind: item.kind, title: item.title, badge, fields: [], actions: [] };
          groups.set(key, group);
        }
        const runnable =
          !!item.action && !!this.collapsedCard(turn, item) && this.canRunAction(item.action);
        if (runnable) group.actions.push(item);
        else if (item.field_label && !group.fields.includes(item.field_label)) {
          group.fields.push(item.field_label);
        }
      }
      return [...groups.values()];
    },
    collapsedActionLabel(item: CollapsedItem, siblings: number): string {
      const action = item.action!;
      if (siblings > 1 && action.kind === 'go_to_table_cell') {
        return String(this.$t('validation_assistant_table_row', { row: (action.row_index ?? 0) + 1 }));
      }
      return this.actionLabel(action);
    },
    collapsedBadge(item: CollapsedItem): string {
      if (item.kind === 'finding') return item.area ? this.areaLabel(item.area) : '';
      if (item.kind !== 'explainer' || !item.operation) return '';
      if (item.pending) return String(this.$t('validation_assistant_decision_pending'));
      return String(this.$t(`validation_assistant_decision_op_${item.operation}`));
    },
    isDiagnosisVisible(turn: Turn): boolean {
      return !!turn.diagnosis?.finding && turn.diagnosis.status !== 'dismissed';
    },
    diagnosisSentence(finding: DiagnosisFinding): string {
      return sentenceFor(finding.sentence, this.currentLanguage());
    },
    diagnosisEvidence(finding: DiagnosisFinding): string {
      const { runs_checked, runs_without_schema, empty_columns } = finding.evidence;
      if (runs_checked > 0 && runs_without_schema > 0) {
        return String(
          this.$t('validation_assistant_diagnosis_evidence', { n: runs_without_schema, m: runs_checked }),
        );
      }
      if (empty_columns.length) {
        return String(
          this.$t('validation_assistant_diagnosis_empty_columns', { columns: empty_columns.join(', ') }),
        );
      }
      return '';
    },
    diagnosisScope(diagnosis: DiagnosisState): string {
      return diagnosis.supplierLabel
        ? String(this.$t('validation_assistant_diagnosis_scope_supplier', { supplier: diagnosis.supplierLabel }))
        : String(this.$t('validation_assistant_diagnosis_scope_document'));
    },
    diagnosisPermission(finding: DiagnosisFinding): string {
      if (finding.route === 'apply') return String(this.$t('validation_assistant_diagnosis_may_yes'));
      if (finding.route === 'forward_to_admin') {
        return String(this.$t('validation_assistant_diagnosis_may_admin'));
      }
      return '';
    },
    diagnosisButtonsOf(turn: Turn): DiagnosisButton[] {
      const diagnosis = turn.diagnosis;
      if (!diagnosis || ['forwarded', 'dismissed', 'settings'].includes(diagnosis.status)) return [];
      return diagnosisButtons(diagnosis.finding);
    },
    docHref(docId: string): string {
      const path = `/field_validation/${encodeURIComponent(docId)}`;
      try {
        return this.$router.resolve(path)?.href || path;
      } catch {
        return path;
      }
    },
    async pickSymptom(chip: AssistantExampleChip) {
      const entry = SYMPTOM_CHIPS.find((item) => item.key === chip.key);
      if (!entry || this.diagnosing || this.isStreaming || !this.chatEnabled) return;
      this.diagnosing = true;
      const language = this.currentLanguage();
      try {
        const result = await validationAssistantService.diagnose({
          doc_id: this.docId,
          symptom: entry.symptom,
          lang: language === 'de' ? 'de' : 'en',
        });
        const [top, ...others] = result.findings;
        if (!top) {
          this.pushNotice(String(this.$t('validation_assistant_diagnosis_none')));
          return;
        }
        const collapsed: CollapsedItem[] = others.map((finding) => ({
          kind: 'finding',
          id: `diagnosis:${finding.code}`,
          offer_id: null,
          title: sentenceFor(finding.sentence, language),
          field_label: null,
          operation: null,
          pending: false,
          area: 'tables',
          action: null,
        }));
        this.turns.push({
          role: 'system',
          text: String(this.$t('validation_assistant_diagnosis_intro', { symptom: chip.label })),
          diagnosis: {
            symptom: entry.symptom,
            tableName: result.table_name,
            supplierLabel: result.supplier_label,
            finding: top,
            status: 'open',
          },
          ...(collapsed.length
            ? { collapsed, collapsedCards: {}, moreCount: collapsed.length, moreOpen: false }
            : {}),
        });
        this.scrollToBottom();
      } catch (error) {
        const status = (error as { status?: number })?.status;
        this.pushNotice(
          String(this.$t(status === 429 ? 'settings_assistant_rate_limited' : 'validation_assistant_diagnosis_failed')),
        );
      } finally {
        this.diagnosing = false;
      }
    },
    dismissDiagnosis(turn: Turn) {
      if (turn.diagnosis?.status === 'open') turn.diagnosis.status = 'dismissed';
    },
    // [Ja, zeigen]: the closed-vocabulary suggestion, then a preview on up to 3 invoices
    async showDiagnosisTags(turn: Turn) {
      const diagnosis = turn.diagnosis;
      if (!diagnosis || diagnosis.status !== 'open') return;
      diagnosis.status = 'suggesting';
      const language = this.currentLanguage();
      try {
        const suggestion = await validationAssistantService.suggestAiTags({
          doc_id: this.docId,
          table_name: diagnosis.tableName,
          wanted_column: diagnosis.finding.evidence.empty_columns[0] || null,
        });
        if (suggestion.not_a_tag) {
          this.pushNotice(sentenceFor(suggestion.not_a_tag.sentence, language));
          return;
        }
        const sure = suggestion.candidates.filter((c) => c.confidence === 'high');
        const tags = (sure.length ? sure : suggestion.candidates.slice(0, 1)).map((c) => c.tag);
        if (!tags.length) {
          this.pushNotice(String(this.$t('validation_assistant_diagnosis_tags_none')));
          return;
        }
        const preview = await validationAssistantService.previewAiTags({
          doc_id: this.docId,
          tags,
          table_name: suggestion.table_name || diagnosis.tableName,
        });
        this.turns.push({
          role: 'system',
          text: String(this.$t('validation_assistant_diagnosis_preview_intro')),
          aiTagPreview: {
            preview,
            finding: diagnosis.finding,
            supplierLabel: diagnosis.supplierLabel,
            receivedAt: Date.now(),
            applied: null,
            forwarding: false,
            forwarded: false,
          },
        });
        this.scrollToBottom();
      } catch (error) {
        const { status, code } = (error || {}) as { status?: number; code?: string };
        let key = 'validation_assistant_diagnosis_failed';
        if (code === 'NOTHING_TO_PREVIEW') key = 'validation_assistant_diagnosis_nothing_to_preview';
        else if (code === 'AI_TAGS_NOT_ALLOWED' || status === 403) key = 'validation_assistant_diagnosis_not_allowed';
        else if (status === 429) key = 'settings_assistant_rate_limited';
        this.pushNotice(String(this.$t(key)));
      } finally {
        diagnosis.status = 'open';
      }
    },
    async showDiagnosisSetting(turn: Turn) {
      const diagnosis = turn.diagnosis;
      if (
        !diagnosis ||
        diagnosis.status !== 'open' ||
        !diagnosisButtons(diagnosis.finding).includes('settings_action')
      )
        return;
      if (diagnosis.finding.settings_offer) {
        diagnosis.status = 'settings';
        return;
      }
      diagnosis.status = 'previewing';
      const params = {
        doc_id: this.docId,
        ...(diagnosis.tableName ? { table_name: diagnosis.tableName } : {}),
      };
      try {
        const offer = toSettingsActionOffer(
          await settingsAssistantSettingsActionService.preview(
            'structured_output_for_supplier',
            params,
          ),
          params,
        );
        if (!offer) throw new Error('invalid preview');
        diagnosis.finding.settings_offer = offer;
        diagnosis.status = 'settings';
      } catch (error) {
        const { status, errorCode } = (error || {}) as {
          status?: number;
          errorCode?: string;
        };
        let key = 'settings_assistant_action_error';
        if (status === 429) key = 'settings_assistant_rate_limited';
        else if (status === 403)
          key = 'validation_assistant_diagnosis_not_allowed';
        else if (errorCode === 'SETTINGS_ACTION_NOTHING_TO_DO')
          key = 'settings_assistant_action_nothing_to_do';
        this.pushNotice(String(this.$t(key)));
      } finally {
        if (diagnosis.status === 'previewing') diagnosis.status = 'open';
      }
    },
    // true when the request went out; the notice says how it went
    async forwardFinding(finding: DiagnosisFinding): Promise<boolean> {
      try {
        await validationAssistantImprovementService.create(this.docId, diagnosisOfferId(finding));
        this.pushNotice(String(this.$t('validation_assistant_diagnosis_forwarded')));
        return true;
      } catch (error) {
        const status = (error as { status?: number })?.status;
        this.pushNotice(
          String(
            this.$t(
              status === 429
                ? 'validation_assistant_improvement_rate_limited'
                : 'validation_assistant_diagnosis_forward_failed',
            ),
          ),
        );
        return false;
      }
    },
    async forwardDiagnosis(turn: Turn) {
      const diagnosis = turn.diagnosis;
      if (!diagnosis || diagnosis.status !== 'open') return;
      diagnosis.status = 'forwarding';
      diagnosis.status = (await this.forwardFinding(diagnosis.finding)) ? 'forwarded' : 'open';
    },
    async forwardPreview(turn: Turn) {
      const state = turn.aiTagPreview;
      if (!state || state.forwarding || state.forwarded) return;
      state.forwarding = true;
      state.forwarded = await this.forwardFinding(state.finding);
      state.forwarding = false;
    },
    onAiTagsApplied(turn: Turn, applied: AiTagApplied, tableWritten = false) {
      if (turn.aiTagPreview) turn.aiTagPreview.applied = applied;
      if (tableWritten) this.reloadAiTable();
    },
    onAiTagsUndone(turn: Turn, tableRestored = false) {
      if (turn.aiTagPreview?.applied) turn.aiTagPreview.applied = { ...turn.aiTagPreview.applied, undone: true };
      if (tableRestored) this.reloadAiTable();
    },
    // the window relay forwards this to the opener's form
    reloadAiTable() {
      document.dispatchEvent(new CustomEvent(RELOAD_AI_TABLE_EVENT, { detail: { doc_id: this.docId } }));
    },
    // CORE-6249: silent by design -- 403/404/disabled/any failure shows nothing.
    async loadImprovements() {
      this.improvementsAbort?.abort();
      this.improvementsAbort = null;
      this.improvements = [];
      const docId = this.docId;
      if (!docId || !this.orgEnabled) return;
      const language = this.currentLanguage();
      const cached = getCachedImprovements(docId, language);
      if (cached) {
        this.improvements = cached;
        return;
      }
      const controller = new AbortController();
      this.improvementsAbort = controller;
      try {
        const found = await validationAssistantExplainerService.getImprovements(
          docId,
          language,
          controller.signal,
        );
        if (controller.signal.aborted) return;
        setCachedImprovements(docId, language, found);
        this.improvements = found;
      } catch {
        // nothing to show; the chat still works
      } finally {
        if (this.improvementsAbort === controller) this.improvementsAbort = null;
      }
    },

    onResize(width: number) {
      setValidationAssistantWidth(width);
    },
    onResetWidth() {
      resetValidationAssistantWidth();
    },
    onWindowResize() {
      this.windowWidth = window.innerWidth;
      const width = validationAssistantWidth.width;
      if (width && width > this.maxWidth) setValidationAssistantWidth(this.maxWidth);
    },

    resetConversation() {
      this.abort?.abort();
      this.turns = [];
      this.error = null;
      this.lastHistory = null;
      this.conversationId = newConversationId();
    },
    /** CORE-6161: plain copy of the chat, shared between docked panel and popout. */
    exportConversation(): ConversationState {
      return {
        turns: JSON.parse(JSON.stringify(this.turns)) as Turn[],
        conversationId: this.conversationId,
      };
    },
    importConversation(state: ConversationState | null) {
      if (!state || !Array.isArray(state.turns)) return;
      this.abort?.abort();
      this.turns = state.turns.filter(
        (turn) => turn && typeof turn === 'object' && turn.role,
      );
      // a call that was running when the copy was taken is not running here
      for (const turn of this.turns) {
        const status = turn.diagnosis?.status;
        if (
          turn.diagnosis &&
          (status === 'suggesting' ||
            status === 'previewing' ||
            status === 'forwarding')
        ) {
          turn.diagnosis.status = 'open';
        }
        if (turn.aiTagPreview) turn.aiTagPreview.forwarding = false;
      }
      if (typeof state.conversationId === 'string' && state.conversationId) {
        this.conversationId = state.conversationId;
      }
      this.error = null;
      this.lastHistory = null;
      this.isStreaming = false;
      this.streamingText = '';
      this.$nextTick(() => this.scrollToBottom());
    },
    emitConversationChange() {
      if (this.isStreaming) return;
      const state = this.exportConversation();
      saveConversation(this.docId, state);
      this.$emit('conversation-change', state);
    },
    toggleSuggestions() {
      this.suggestionsOpen = !this.suggestionsOpen;
      try {
        localStorage.setItem(SUGGESTIONS_OPEN_KEY, String(this.suggestionsOpen));
      } catch {
        // storage unavailable: the choice lasts for this view only
      }
    },
    startNewChat() {
      if (this.isStreaming || !this.turns.length) return;
      this.resetConversation();
      this.$nextTick(() => this.focusInput());
    },
    focusInput() {
      (this.$refs.composer as { focus?: () => void } | undefined)?.focus?.();
    },
    async ask(question: string) {
      if (!this.chatEnabled || this.isStreaming) return;
      await this.sendText(this.$t(question));
    },
    async send() {
      const text = this.draft.trim();
      if (!text || this.isStreaming || !this.chatEnabled) return;
      this.draft = '';
      await this.sendText(text);
    },
    async sendText(text: string) {
      this.turns.push({ role: 'user', text });
      const history: AssistantTurn[] = this.turns
        .filter(
          (turn): turn is Turn & { role: 'user' | 'assistant' } =>
            turn.role === 'user' || (turn.role === 'assistant' && !!turn.text),
        )
        .map((turn) => ({ role: turn.role, content: turn.text }))
        .slice(-MAX_HISTORY_TURNS);
      await this.runTurn(history);
    },
    retry() {
      if (this.lastHistory && !this.isStreaming) {
        void this.runTurn(this.lastHistory);
      }
    },
    stopStreaming() {
      this.abort?.abort();
    },
    currentLanguage(): string {
      return String(this.tolgee.getLanguage() || 'de').slice(0, 2).toLowerCase();
    },
    renderMarkdown(text: string): string {
      return renderAssistantMarkdown(sanitizeAiModelIds(asBulletList(text), this.$t), {
        docLinkLabel: String(this.$t('settings_assistant_doc_link')),
      });
    },
    persistStreamed(
      actions: AssistantAction[],
      findings: AssistantFinding[],
      rulePreview: RulePreview | null = null,
      settingsActions: SettingsActionOffer[] = [],
      explainers: Explainer[] = [],
      capped: CappedAnswer | null = null,
    ) {
      if (
        !this.streamingText &&
        !actions.length &&
        !findings.length &&
        !rulePreview &&
        !settingsActions.length &&
        !explainers.length &&
        !capped?.moreCount
      )
        return;
      const collapsedCards: Record<string, ActionCardState> = {};
      for (const item of capped?.collapsed || []) {
        if (item.action) collapsedCards[item.id] = { action: item.action, status: 'idle' };
      }
      this.turns.push({
        role: 'assistant',
        text: this.streamingText,
        actions: actions.map((action) => ({ action, status: 'idle' })),
        findings,
        ...(rulePreview ? { rulePreview } : {}),
        ...(settingsActions.length ? { settingsActions } : {}),
        ...(explainers.length ? { explainers } : {}),
        ...(capped
          ? {
              collapsed: capped.collapsed,
              collapsedCards,
              moreCount: capped.moreCount,
              moreOpen: false,
            }
          : {}),
      });
    },
    async runTurn(history: AssistantTurn[]) {
      this.error = null;
      this.isStreaming = true;
      this.streamingText = '';
      this.lastHistory = history;
      this.abort = new AbortController();
      const actions: AssistantAction[] = [];
      const findings: AssistantFinding[] = [];
      let rulePreview: RulePreview | null = null;
      const settingsActions: SettingsActionOffer[] = [];
      const explainers: Explainer[] = [];
      let capped: CappedAnswer | null = null;
      this.scrollToBottom();
      try {
        for await (const chunk of validationAssistantService.chat(
          {
            doc_id: this.docId,
            messages: history,
            language: this.currentLanguage(),
            conversation_id: this.conversationId,
            session_changes: capSessionChanges(this.sessionChanges),
            screen: this.screen as AssistantScreen,
          },
          this.abort.signal,
        )) {
          if (chunk.type === 'text') {
            this.streamingText += chunk.delta;
            this.scrollToBottom();
          } else if (chunk.type === 'capabilities') {
            this.capabilities = normalizeAssistantCapabilities(chunk.capabilities);
          } else if (chunk.type === 'finding') {
            const finding = normalizeAssistantFinding(chunk.finding);
            if (finding && !findings.some((known) => known.id === finding.id)) {
              findings.push(this.canSeeSetup ? finding : { ...finding, admin: undefined });
            }
          } else if (chunk.type === 'action') {
            const action = normalizeAssistantAction(chunk.action);
            if (action && !actions.some((known) => known.id === action.id)) {
              actions.push(action);
            }
          } else if ((chunk as { type: string }).type === 'rule_preview') {
            // CORE-6145 — validated before it is rendered; malformed = no card.
            const payload = (chunk as { rule_preview?: unknown }).rule_preview;
            if (isRulePreview(payload)) rulePreview = payload;
          } else if ((chunk as { type: string }).type === 'settings_actions') {
            // accumulate like the other chunk types; one card per preview
            for (const offer of parseSettingsActionOffers(
              (chunk as { items?: unknown }).items,
            )) {
              if (!settingsActions.some((k) => k.preview_id === offer.preview_id)) {
                settingsActions.push(offer);
              }
            }
          } else if ((chunk as { type: string }).type === 'explainer') {
            // CORE-6235 — accumulate; malformed explainers are dropped, not half-drawn
            for (const explainer of parseExplainers(
              (chunk as { explainers?: unknown }).explainers,
            )) {
              if (!explainers.some((k) => k.id === explainer.id)) {
                explainers.push(explainer);
              }
            }
            // CORE-6307: the improvement answer -- the rest behind ONE "N more"
            const chunkMore = chunk as { collapsed?: unknown; more_count?: unknown };
            if ('more_count' in chunkMore || 'collapsed' in chunkMore) {
              const collapsed = parseCollapsedItems(chunkMore.collapsed);
              capped = { collapsed, moreCount: parseMoreCount(chunkMore.more_count, collapsed) };
            }
          }
        }
        this.persistStreamed(
          actions,
          findings,
          rulePreview,
          settingsActions,
          explainers,
          capped,
        );
        this.lastHistory = null;
      } catch (err: unknown) {
        if ((err as { name?: string })?.name === 'AbortError') {
          this.persistStreamed(
          actions,
          findings,
          rulePreview,
          settingsActions,
          explainers,
          capped,
        );
          return;
        }
        if (err instanceof AssistantUnavailableError) {
          this.error = { traceId: '', retryable: true, kind: 'unavailable' };
        } else if (err instanceof AssistantStreamTimeoutError) {
          this.error = { traceId: '', retryable: true, kind: 'timeout' };
        } else if (err instanceof AssistantRequestError) {
          if (err.status === 429) {
            this.error = { traceId: err.traceId, retryable: true, kind: 'rate_limited' };
          } else if (err.status === 403) {
            this.error = { traceId: err.traceId, kind: 'forbidden' };
          } else if (err.status === 503) {
            this.error = { traceId: err.traceId, retryable: true, kind: 'unavailable' };
          } else {
            this.error = { traceId: err.traceId, retryable: true };
          }
        } else {
          this.error = { traceId: '', retryable: true };
        }
      } finally {
        this.isStreaming = false;
        this.streamingText = '';
        this.abort = null;
        this.scrollToBottom();
      }
    },
    /** CORE-6307 — "Apply to this document": the value goes into the FORM only
     * (saved with the document, undo like every assistant change). */
    applyFormAction(action: AssistantAction) {
      if (!this.canRunAction(action)) return;
      void this.runAction({ action, status: 'idle' });
    },
    /** CORE-6235 — "Apply" on an explainer only points at the existing apply card. */
    onExplainerApply(ref: ExplainerApplyRef) {
      const root = this.$el as HTMLElement | undefined;
      const target = Array.from(
        root?.querySelectorAll<HTMLElement>('[data-apply-ref]') ?? [],
      ).find((el) => el.getAttribute('data-apply-ref') === ref.id);
      // CORE-6307: a panel suggestion has no apply card yet -- the chat builds it
      if (!target) {
        void this.askImprove();
        return;
      }
      const reduced =
        typeof window !== 'undefined' &&
        !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
      target.scrollIntoView?.({
        behavior: reduced ? 'auto' : 'smooth',
        block: 'center',
      });
      target.setAttribute('tabindex', '-1');
      target.focus?.({ preventScroll: true });
      target.classList.add('validation-assistant__apply-highlight');
      if (this.highlightTimer) clearTimeout(this.highlightTimer);
      this.highlightTimer = setTimeout(() => {
        target.classList.remove('validation-assistant__apply-highlight');
        this.highlightTimer = null;
      }, 2400);
    },
    scrollToBottom() {
      (this.$refs.messageList as { scrollToBottom?: () => void } | undefined)?.scrollToBottom?.();
    },
  },
});
</script>

