/**
 * CORE-6161 popout: cross-window messaging between the validation screen and
 * the assistant's own browser window.
 *
 * A window shares no Pinia state with its opener, and the assistant's actions
 * talk to the screen over DOM events on `document`. The window therefore
 * redirects those events onto the opener's `document` (which is already
 * listening) and bridges the reply `FIELD_ACTION_RESULT_EVENT` back.
 *
 * The blocker snapshot is pushed two ways — a direct `window` reference while
 * the opener is alive, and a BroadcastChannel that survives the opener
 * navigating or reloading (where the reference goes stale).
 */
import { FOCUS_BLOCKED_FIELD_EVENT, FOCUS_BLOCKED_TABLE_EVENT } from './validationBlockers';
import {
  ADD_TABLE_ROW_EVENT,
  APPLY_LOOKUP_CANDIDATE_EVENT,
  CONFIRM_FIELD_EVENT,
  FIELD_ACTION_RESULT_EVENT,
  GO_TO_TABLE_CELL_EVENT,
  OPEN_SUPPORT_TICKET_EVENT,
  OPEN_TASK_FORM_EVENT,
  RECLASSIFY_EVENT,
  RELOAD_AI_TABLE_EVENT,
  REMOVE_TABLE_ROW_EVENT,
  RERUN_LOOKUP_EVENT,
  RESTORE_FIELD_EVENT,
  RESTORE_FIELDS_EVENT,
  RESTORE_TABLE_CELL_EVENT,
  SET_FIELD_VALUE_EVENT,
  SET_TABLE_CELL_EVENT,
  START_FIELD_TRAINING_EVENT,
} from './validationAssistantActions';

export const VALIDATION_ASSISTANT_CHANNEL = 'docbits:validation-assistant';

export interface ValidationAssistantBusMessage {
  type: 'blockers' | 'chat-moved';
  snapshot?: unknown;
  /** The document the snapshot belongs to — the window follows the opener. */
  docId?: string;
}

/**
 * The events the assistant's action cards and chips fire on `document`. In the
 * popup window these listeners live on the opener's `document`, so the window
 * redirects them there.
 */
const OPENER_BOUND_EVENTS = [
  FOCUS_BLOCKED_FIELD_EVENT,
  FOCUS_BLOCKED_TABLE_EVENT,
  SET_FIELD_VALUE_EVENT,
  CONFIRM_FIELD_EVENT,
  RESTORE_FIELD_EVENT,
  GO_TO_TABLE_CELL_EVENT,
  SET_TABLE_CELL_EVENT,
  RESTORE_TABLE_CELL_EVENT,
  ADD_TABLE_ROW_EVENT,
  REMOVE_TABLE_ROW_EVENT,
  APPLY_LOOKUP_CANDIDATE_EVENT,
  RERUN_LOOKUP_EVENT,
  RESTORE_FIELDS_EVENT,
  RECLASSIFY_EVENT,
  START_FIELD_TRAINING_EVENT,
  OPEN_SUPPORT_TICKET_EVENT,
  OPEN_TASK_FORM_EVENT,
  RELOAD_AI_TABLE_EVENT,
];

const RESULT_EVENT = FIELD_ACTION_RESULT_EVENT;

export function openerWindow(): Window | null {
  try {
    return window.opener && !window.opener.closed ? window.opener : null;
  } catch {
    return null;
  }
}

export function openerDocument(): Document | null {
  const opener = openerWindow();
  try {
    return opener?.document ?? null;
  } catch {
    return null;
  }
}

let broadcastChannel: BroadcastChannel | null = null;

function channel(): BroadcastChannel | null {
  if (typeof BroadcastChannel === 'undefined') return null;
  if (!broadcastChannel) {
    try {
      broadcastChannel = new BroadcastChannel(VALIDATION_ASSISTANT_CHANNEL);
    } catch {
      broadcastChannel = null;
    }
  }
  return broadcastChannel;
}

export function broadcastValidationAssistant(message: ValidationAssistantBusMessage) {
  try {
    channel()?.postMessage(message);
  } catch {
    // no-op: the channel is best-effort
  }
}

/**
 * The popup window's relay: redirects a request event fired on the local
 * `document` to the opener's `document`, then bridges the reply event back.
 * Returns a cleanup function.
 *
 * Only the window installs this; the docked panel talks to its own screen.
 */
export function installWindowActionRelay(): () => void {
  const target = openerDocument();
  if (!target) return () => undefined;

  const forward = (event: Event) => {
    const name = event.type;
    if (!OPENER_BOUND_EVENTS.includes(name)) return;
    // Keep the same detail and requestId; the opener answers on its document.
    target.dispatchEvent(
      new CustomEvent(name, { detail: (event as CustomEvent).detail }),
    );
  };
  const captureResult = (event: Event) => {
    // The opener answered on its own document; re-fire locally so the
    // requestFieldAction promise in this window resolves.
    const detail = (event as CustomEvent).detail;
    if (!detail?.requestId) return;
    document.dispatchEvent(new CustomEvent(RESULT_EVENT, { detail }));
  };

  for (const name of OPENER_BOUND_EVENTS) document.addEventListener(name, forward);
  target.addEventListener(RESULT_EVENT, captureResult);

  return () => {
    for (const name of OPENER_BOUND_EVENTS) document.removeEventListener(name, forward);
    target.removeEventListener(RESULT_EVENT, captureResult);
  };
}