<template>
  <div
    class="assistant-nav-row"
    :class="variant !== 'default' ? `assistant-nav-row--${variant}` : ''"
    :data-test="`${testId}-nav-row`"
  >
    <div class="assistant-nav-row__text">
      <span class="assistant-nav-row__title">{{ title }}</span>
      <span v-if="summary" class="assistant-nav-row__summary">{{ summary }}</span>
      <span v-if="reason" class="assistant-nav-row__reason">{{ reason }}</span>
    </div>
    <div class="assistant-nav-row__chips">
      <button
        v-for="chip in visibleChips"
        :key="chip.key"
        type="button"
        class="assistant-nav-row__chip"
        :disabled="disabled"
        :data-test="chip.test || `${testId}-nav-chip`"
        :data-key="chip.key"
        @click="$emit('pick', chip.key)"
      >
        {{ chip.label }}
      </button>
      <button
        v-if="hiddenCount"
        type="button"
        class="assistant-nav-row__chip assistant-nav-row__chip--more"
        :data-test="`${testId}-nav-more`"
        @click="expanded = true"
      >
        +{{ hiddenCount }}
      </button>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';

export default defineComponent({
  name: 'AssistantNavRow',

  props: {
    title: { type: String, required: true },
    summary: { type: String, default: '' },
    reason: { type: String, default: '' },
    chips: {
      type: Array as PropType<{ key: string; label: string; test?: string }[]>,
      default: () => [],
    },
    limit: { type: Number, default: 5 },
    variant: {
      type: String as PropType<'default' | 'warning' | 'danger'>,
      default: 'default',
    },
    disabled: { type: Boolean, default: false },
    testId: { type: String, default: 'assistant' },
  },

  emits: ['pick'],

  data() {
    return { expanded: false };
  },

  computed: {
    visibleChips(): { key: string; label: string; test?: string }[] {
      return this.expanded ? this.chips : this.chips.slice(0, this.limit);
    },
    hiddenCount(): number {
      return this.chips.length - this.visibleChips.length;
    },
  },
});
</script>

