<!-- CORE-6454: extra AI columns for the supplier, before → after on up to 3 invoices; save, then undo for 15 minutes. -->
<template>
  <div class="ai-tag-preview" data-test="validation-assistant-ai-tag-preview" :data-verdict="preview.verdict">
    <AssistantActionCard
      v-if="state !== 'declined'"
      :variant="cardVariant"
      :kicker="$t('validation_assistant_diagnosis_preview_kicker')"
      :title="verdictText"
      test-id="validation-assistant"
    >
      <ul v-if="preview.documents.length" class="ai-tag-preview__docs">
        <li
          v-for="(doc, docIndex) in preview.documents"
          :key="doc.doc_id"
          data-test="validation-assistant-ai-tag-preview-doc"
        >
          <span class="ai-tag-preview__doc-name">{{
            doc.is_current
              ? $t('validation_assistant_diagnosis_preview_this_invoice')
              : $t('validation_assistant_diagnosis_example', { n: docIndex + 1 })
          }}</span>
          <span v-if="doc.error" class="ai-tag-preview__muted">{{
            $t('validation_assistant_diagnosis_preview_doc_failed')
          }}</span>
          <template v-else>
            <span
              v-for="label in shownLabels"
              :key="label"
              class="ai-tag-preview__count"
              data-test="validation-assistant-ai-tag-preview-count"
              >{{ label }}: {{ doc.before[label] ?? 0 }} → <strong>{{ doc.after[label] ?? 0 }}</strong></span
            >
          </template>
        </li>
      </ul>

      <div v-if="currentRows.length" class="ai-tag-preview__table-wrap">
        <table class="ai-tag-preview__table" data-test="validation-assistant-ai-tag-preview-rows">
          <thead>
            <tr>
              <th v-for="column in rowColumns" :key="column">{{ column }}</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="(row, rowIndex) in currentRows" :key="rowIndex">
              <td v-for="column in rowColumns" :key="column">{{ cellText(row[column]) }}</td>
            </tr>
          </tbody>
        </table>
      </div>

      <p
        v-if="preview.summary.columns_lost.length"
        class="ai-tag-preview__warning"
        data-test="validation-assistant-ai-tag-preview-lost"
      >
        {{ $t('validation_assistant_diagnosis_preview_lost', { columns: preview.summary.columns_lost.join(', ') }) }}
      </p>

      <p v-if="messageKey" class="ai-tag-preview__message" role="status" data-test="validation-assistant-ai-tag-preview-message">
        {{ $t(messageKey) }}
      </p>

      <AssistantAppliedChangeLine
        v-if="state === 'applied' || state === 'undoing' || state === 'undone'"
        :content="$t('validation_assistant_diagnosis_applied', { supplier: supplierName })"
        :undone="state === 'undone'"
        :expires-at="applied ? applied.undoExpiresAt : null"
        :now-ms="now"
        :undone-label="$t('validation_assistant_action_undone')"
        test-id="validation-assistant-ai-tag"
      >
        <template #action>
          <q-btn
            flat
            dense
            no-caps
            color="primary"
            size="sm"
            :label="$t('undo')"
            :loading="state === 'undoing'"
            :disable="state !== 'applied'"
            data-test="validation-assistant-ai-tag-undo"
            @click="undo"
          />
        </template>
      </AssistantAppliedChangeLine>

      <template v-if="showActions" #actions>
        <template v-if="canApply">
          <q-btn
            unelevated
            no-caps
            color="primary"
            class="validation-assistant__action-btn"
            :loading="state === 'applying'"
            :disable="state !== 'offered' || tokenExpired"
            :label="$t('validation_assistant_diagnosis_remember', { supplier: supplierName })"
            data-test="validation-assistant-ai-tag-apply"
            @click="apply"
          />
          <q-btn
            outline
            no-caps
            color="primary"
            class="validation-assistant__action-btn"
            :disable="state !== 'offered'"
            :label="$t('validation_assistant_diagnosis_no')"
            data-test="validation-assistant-ai-tag-decline"
            @click="decline"
          />
        </template>
        <q-btn
          v-else-if="!forwarded"
          unelevated
          no-caps
          color="primary"
          class="validation-assistant__action-btn"
          :loading="forwarding"
          :disable="forwarding"
          :label="$t('validation_assistant_diagnosis_forward')"
          data-test="validation-assistant-ai-tag-forward"
          @click="$emit('forward')"
        />
      </template>
    </AssistantActionCard>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import AssistantActionCard from 'src/components/AssistantChat/AssistantActionCard.vue';
import AssistantAppliedChangeLine from 'src/components/AssistantChat/AssistantAppliedChangeLine.vue';
import { validationAssistantService } from 'src/services/validationAssistant/validationAssistantService';
import { sentenceFor, type AiTagPreview } from 'src/utils/validationAssistant/diagnosis';

export interface AiTagApplied {
  operationId: string;
  undoExpiresAt: number;
  undone: boolean;
}

type CardState = 'offered' | 'applying' | 'applied' | 'undoing' | 'undone' | 'declined';

const MAX_ROWS = 10;
const TICK_MS = 30_000;

export default defineComponent({
  name: 'ValidationAssistantAiTagPreviewCard',

  components: { AssistantActionCard, AssistantAppliedChangeLine },

  props: {
    preview: { type: Object as PropType<AiTagPreview>, required: true },
    supplierLabel: { type: String as PropType<string | null>, default: null },
    language: { type: String, default: 'de' },
    // epoch ms when the preview arrived; the token lives expires_in_seconds from there
    receivedAt: { type: Number, default: () => Date.now() },
    applied: { type: Object as PropType<AiTagApplied | null>, default: null },
    forwarded: { type: Boolean, default: false },
    forwarding: { type: Boolean, default: false },
  },

  emits: ['applied', 'undone', 'forward'],

  data() {
    const applied = this.applied as AiTagApplied | null;
    return {
      state: (applied ? (applied.undone ? 'undone' : 'applied') : 'offered') as CardState,
      now: Date.now(),
      messageKey: '',
      timer: null as ReturnType<typeof setInterval> | null,
    };
  },

  computed: {
    canApply(): boolean {
      const { verdict, preview_token } = this.preview;
      return !!preview_token && (verdict === 'ok' || verdict === 'partial');
    },
    showActions(): boolean {
      if (this.canApply) return this.state === 'offered' || this.state === 'applying';
      return this.preview.verdict === 'failed' || this.preview.verdict === 'stopped';
    },
    cardVariant(): 'default' | 'warning' {
      return this.canApply && this.preview.verdict === 'ok' ? 'default' : 'warning';
    },
    supplierName(): string {
      return this.supplierLabel || String(this.$t('validation_assistant_diagnosis_this_supplier'));
    },
    tokenExpired(): boolean {
      return this.now >= this.receivedAt + this.preview.expires_in_seconds * 1000;
    },
    verdictText(): string {
      const { verdict, summary, sentence } = this.preview;
      if (verdict === 'stopped') {
        return sentence
          ? sentenceFor(sentence, this.language)
          : String(this.$t('validation_assistant_diagnosis_verdict_stopped'));
      }
      return String(
        this.$t(`validation_assistant_diagnosis_verdict_${verdict}`, {
          n: summary.wanted_present_in,
          m: summary.documents,
        }),
      );
    },
    shownLabels(): string[] {
      const labels = this.preview.wanted_columns.map((w) => w.column_label);
      for (const lost of this.preview.summary.columns_lost) if (!labels.includes(lost)) labels.push(lost);
      return labels;
    },
    currentRows(): Record<string, unknown>[] {
      return (this.preview.documents.find((d) => d.is_current)?.rows || []).slice(0, MAX_ROWS);
    },
    rowColumns(): string[] {
      const columns: string[] = [];
      for (const row of this.currentRows) {
        for (const key of Object.keys(row)) if (!columns.includes(key)) columns.push(key);
      }
      return columns;
    },
  },

  mounted() {
    this.timer = setInterval(() => {
      this.now = Date.now();
    }, TICK_MS);
  },

  beforeUnmount() {
    if (this.timer) clearInterval(this.timer);
  },

  methods: {
    cellText(value: unknown): string {
      if (value === null || value === undefined) return '';
      return typeof value === 'object' ? JSON.stringify(value) : String(value);
    },
    decline() {
      if (this.state === 'offered') this.state = 'declined';
    },
    async apply() {
      const token = this.preview.preview_token;
      if (!token || this.state !== 'offered') return;
      this.now = Date.now();
      if (this.tokenExpired) {
        this.messageKey = 'validation_assistant_diagnosis_preview_expired';
        return;
      }
      this.state = 'applying';
      this.messageKey = '';
      try {
        const result = await validationAssistantService.applyAiTags(token);
        this.now = Date.now();
        const applied: AiTagApplied = {
          operationId: result.operation_id,
          undoExpiresAt: this.now + result.undo_expires_in_seconds * 1000,
          undone: false,
        };
        this.state = 'applied';
        this.$emit('applied', applied, result.table_written);
      } catch (err) {
        this.state = 'offered';
        this.messageKey = this.applyErrorKey(err);
      }
    },
    async undo() {
      const applied = this.applied;
      if (!applied || this.state !== 'applied') return;
      this.now = Date.now();
      if (this.now >= applied.undoExpiresAt) {
        this.messageKey = 'validation_assistant_diagnosis_undo_expired';
        return;
      }
      this.state = 'undoing';
      this.messageKey = '';
      try {
        const result = await validationAssistantService.undoAiTags(applied.operationId);
        this.state = 'undone';
        this.$emit('undone', !!result?.table_restored);
      } catch (err) {
        this.state = 'applied';
        this.messageKey = this.undoErrorKey(err);
      }
    },
    applyErrorKey(err: unknown): string {
      const { status, code } = (err || {}) as { status?: number; code?: string };
      if (code === 'CHANGED_SINCE') return 'validation_assistant_diagnosis_changed_since';
      if (code === 'DOCUMENT_LOCKED') return 'validation_assistant_diagnosis_locked';
      if (status === 404) return 'validation_assistant_diagnosis_preview_expired';
      return 'validation_assistant_diagnosis_apply_failed';
    },
    undoErrorKey(err: unknown): string {
      const { status } = (err || {}) as { status?: number };
      if (status === 409) return 'validation_assistant_diagnosis_undo_changed_since';
      if (status === 410) return 'validation_assistant_diagnosis_undo_expired';
      return 'validation_assistant_diagnosis_undo_failed';
    },
  },
});
</script>

