/**
 * CORE-6249 — the canonical "What can I improve?" question per app language.
 *
 * doc2-api answers exactly these phrasings deterministically
 * (`module/validation_assistant/improve_intent.py`, CORE-6237): the document is
 * always read and the improvement explainers are built. A language the
 * detector does not know falls back to English, which it does know, so the
 * question never depends on the classifier guessing.
 */
const IMPROVE_QUESTIONS: Record<string, string> = {
  en: 'What can I improve on this document?',
  de: 'Was kann ich an diesem Dokument noch verbessern?',
  fr: 'Que puis-je améliorer sur ce document ?',
  es: '¿Qué puedo mejorar en este documento?',
  it: 'Cosa posso migliorare su questo documento?',
  pt: 'O que posso melhorar neste documento?',
};

/** `language` is the app language, e.g. "de", "pt-BR". */
export function improveQuestion(language: string): string {
  const base = String(language || '')
    .slice(0, 2)
    .toLowerCase();
  return IMPROVE_QUESTIONS[base] ?? IMPROVE_QUESTIONS.en;
}
