import { reactive } from 'vue';

// CORE-6161: the validation assistant's dragged width; null keeps the sidebar's default (25vw).
const STORAGE_KEY = 'validation_assistant_width';

export const VALIDATION_ASSISTANT_MIN_WIDTH = 320;
const MAX_WIDTH_CAP = 760;
const MIN_CONTENT_WIDTH_PX = 640;

export function validationAssistantMaxWidth(
  viewportWidth: number = typeof window !== 'undefined' ? window.innerWidth : 1440,
): number {
  return Math.max(
    VALIDATION_ASSISTANT_MIN_WIDTH,
    Math.min(MAX_WIDTH_CAP, Math.round(viewportWidth - MIN_CONTENT_WIDTH_PX)),
  );
}

export function clampValidationAssistantWidth(px: number, viewportWidth?: number): number {
  return Math.min(
    Math.max(Math.round(px), VALIDATION_ASSISTANT_MIN_WIDTH),
    validationAssistantMaxWidth(viewportWidth),
  );
}

function readPersisted(): number | null {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const value = Number(raw);
    return Number.isFinite(value) ? clampValidationAssistantWidth(value) : null;
  } catch {
    return null;
  }
}

export const validationAssistantWidth = reactive({
  width: readPersisted() as number | null,
});

export function setValidationAssistantWidth(px: number) {
  validationAssistantWidth.width = clampValidationAssistantWidth(px);
  try {
    window.localStorage.setItem(STORAGE_KEY, String(validationAssistantWidth.width));
  } catch {
    // storage blocked: the width still applies for this session
  }
}

export function resetValidationAssistantWidth() {
  validationAssistantWidth.width = null;
  try {
    window.localStorage.removeItem(STORAGE_KEY);
  } catch {
    // storage blocked
  }
}
