// CORE-6161: one assistant chat per document, kept while the user moves between
// validation, PO matching and accounting in this tab.
import { defineStore } from 'pinia';

const MAX_DOCS = 20;

export const useAssistantConversationStore = defineStore('validationAssistantConversations', {
  state: () => ({
    // insertion order is the recency order
    byDoc: new Map<string, unknown>(),
  }),
  actions: {
    save(docId: string, state: unknown) {
      if (!docId) return;
      this.byDoc.delete(docId);
      this.byDoc.set(docId, state);
      while (this.byDoc.size > MAX_DOCS) {
        this.byDoc.delete(this.byDoc.keys().next().value as string);
      }
    },
  },
});

export function saveConversation(docId: string, state: unknown) {
  useAssistantConversationStore().save(docId, state);
}

export function loadConversation(docId: string): unknown {
  return docId ? useAssistantConversationStore().byDoc.get(docId) ?? null : null;
}
