// CORE-6161: one assistant answer as a short, sorted list instead of one card per field.
import type { AssistantAction, AssistantFinding } from 'src/utils/validationAssistantActions';

export interface GroupableCard {
  action: AssistantAction;
  status: 'idle' | 'running' | 'done';
}

export type Severity = AssistantFinding['severity'];

export const NAV_KINDS: ReadonlySet<string> = new Set(['go_to_field', 'go_to_table_cell']);
export const CHIP_LIMIT = 5;

export interface NavChip {
  key: string;
  label: string;
  test: string;
  card: GroupableCard;
}

export interface NavGroup {
  key: string;
  kind: 'field' | 'cell';
  title: string;
  reason: string;
  chips: NavChip[];
}

export interface FindingGroup {
  key: string;
  severity: Severity;
  area: string;
  title: string;
  findings: AssistantFinding[];
}

export type TurnItem =
  | { type: 'finding-group'; key: string; group: FindingGroup }
  | { type: 'finding'; key: string; finding: AssistantFinding }
  | { type: 'nav-group'; key: string; group: NavGroup }
  | { type: 'action'; key: string; card: GroupableCard };

const SEVERITY_RANK: Record<Severity, number> = { error: 0, warning: 1, info: 2 };
const NEUTRAL_RANK = 2;
const NAV_RANK = 3;

const DOCUMENT_AREAS = new Set([
  'classification',
  'duplicates',
  'accounting',
  'edoc',
  'edoc_sources',
  'export',
  'export_precheck',
  'status',
  'status_workflow',
  'po_match',
]);
const TABLE_AREAS = new Set(['line_items', 'tables']);
const SETUP_AREAS = new Set(['setup', 'ai_setup', 'ai_tier_supplier']);

// field, then document, table, setup
export function areaRank(area: string | undefined): number {
  if (!area) return 0;
  if (SETUP_AREAS.has(area)) return 3;
  if (TABLE_AREAS.has(area)) return 2;
  if (DOCUMENT_AREAS.has(area)) return 1;
  return 0;
}

export function strongestSeverity(list: Severity[]): Severity {
  return list.reduce<Severity>(
    (best, next) => (SEVERITY_RANK[next] < SEVERITY_RANK[best] ? next : best),
    'info',
  );
}

export function findingFieldNames(finding: AssistantFinding): string[] {
  const names = (finding.fields || []).map((entry) => entry.name).filter(Boolean);
  if (finding.field && !names.includes(finding.field)) names.unshift(finding.field);
  return names;
}

export function cellKey(action: Pick<AssistantAction, 'table' | 'row_index' | 'column'>): string {
  return `${action.table}|${action.row_index}|${action.column}`;
}

// "1-3, 5" for rows 0, 1, 2, 4 (shown 1-based)
export function rowRangeText(rowIndexes: number[]): string {
  const rows = [...new Set(rowIndexes)].sort((a, b) => a - b).map((row) => row + 1);
  const parts: string[] = [];
  let start = rows[0];
  let prev = rows[0];
  for (const row of rows.slice(1).concat(Number.NaN)) {
    if (row === prev + 1) {
      prev = row;
      continue;
    }
    if (start !== undefined) parts.push(start === prev ? String(start) : `${start}-${prev}`);
    start = row;
    prev = row;
  }
  return parts.join(', ');
}

function chipTest(action: AssistantAction): string {
  return `validation-assistant-action-${action.kind}`;
}

/** The same warning on several fields becomes one group; the rest stay single. */
export function splitFindings(findings: AssistantFinding[]): {
  groups: FindingGroup[];
  solo: AssistantFinding[];
} {
  const byKey = new Map<string, AssistantFinding[]>();
  for (const finding of findings) {
    const key = `${finding.area}|${finding.title}`;
    byKey.set(key, [...(byKey.get(key) || []), finding]);
  }
  const groups: FindingGroup[] = [];
  const solo: AssistantFinding[] = [];
  for (const [key, list] of byKey) {
    if (list.length > 1) {
      const severity = strongestSeverity(list.map((entry) => entry.severity));
      groups.push({ key, severity, area: list[0].area, title: list[0].title, findings: list });
    } else {
      solo.push(list[0]);
    }
  }
  return { groups, solo };
}

/**
 * Field jumps grouped by cause, cell jumps by table + column. Jumps to a field
 * or cell that a blocker or finding already names are dropped.
 */
export function groupNavCards(
  cards: GroupableCard[],
  covered: { fields: Set<string>; cells: Set<string> },
  labels: { fieldJump: string; row: (row: number) => string },
): NavGroup[] {
  const groups = new Map<string, NavGroup>();
  for (const card of cards) {
    const action = card.action;
    if (action.kind === 'go_to_field') {
      if (covered.fields.has(action.field)) continue;
      const cause = action.reason_code || action.reason || '';
      const key = `field|${cause}`;
      const group = groups.get(key) || {
        key,
        kind: 'field' as const,
        title: action.reason || labels.fieldJump,
        reason: '',
        chips: [],
      };
      if (!group.chips.some((chip) => chip.key === action.field)) {
        group.chips.push({ key: action.field, label: action.label || action.field, test: chipTest(action), card });
      }
      groups.set(key, group);
    } else if (action.kind === 'go_to_table_cell') {
      if (covered.cells.has(cellKey(action))) continue;
      const key = `cell|${action.table}|${action.column}`;
      const group = groups.get(key) || {
        key,
        kind: 'cell' as const,
        title: action.column_label || action.column || '',
        reason: action.reason || '',
        chips: [],
      };
      const chipKey = String(action.row_index ?? 0);
      if (!group.chips.some((chip) => chip.key === chipKey)) {
        group.chips.push({ key: chipKey, label: labels.row((action.row_index ?? 0) + 1), test: chipTest(action), card });
      }
      groups.set(key, group);
    }
  }
  for (const group of groups.values()) {
    if (group.kind === 'cell') {
      group.chips.sort((a, b) => Number(a.key) - Number(b.key));
    } else if (group.chips.length === 1) {
      // one field: its name as the title, the cause below, a plain "go to field" link
      const chip = group.chips[0];
      group.reason = group.title === labels.fieldJump ? '' : group.title;
      group.title = chip.label;
      chip.label = labels.fieldJump;
    }
  }
  return [...groups.values()];
}

/** Sort: red, orange, neutral, blue; within a level blocking fields first, then document, table, setup. */
export function sortTurnItems(items: TurnItem[], blockingFields: Set<string>): TurnItem[] {
  const rank = (item: TurnItem): [number, number, number] => {
    switch (item.type) {
      case 'finding-group': {
        const blocking = item.group.findings.some((f) => findingFieldNames(f).some((n) => blockingFields.has(n)));
        return [SEVERITY_RANK[item.group.severity], blocking ? 0 : 1, areaRank(item.group.area)];
      }
      case 'finding': {
        const blocking = findingFieldNames(item.finding).some((n) => blockingFields.has(n));
        return [SEVERITY_RANK[item.finding.severity], blocking ? 0 : 1, areaRank(item.finding.area)];
      }
      case 'nav-group':
        return [NAV_RANK, 1, item.group.kind === 'cell' ? 2 : 0];
      default:
        return [NEUTRAL_RANK, 2, 0];
    }
  };
  return items
    .map((item, index) => ({ item, index, rank: rank(item) }))
    .sort((a, b) => {
      for (let i = 0; i < 3; i += 1) {
        if (a.rank[i] !== b.rank[i]) return a.rank[i] - b.rank[i];
      }
      return a.index - b.index;
    })
    .map((entry) => entry.item);
}

// CORE-6454: never more than this many big cards per answer and on the board
export const MAX_VISIBLE_CARDS = 7;

export type CardSlot =
  | 'settings_action'
  | 'rule_preview'
  | 'diagnosis'
  | 'finding'
  | 'explainer'
  | 'action';

// same order as doc2-api answer_cap._CARD_PRIORITY
const CARD_PRIORITY: Record<CardSlot, number> = {
  settings_action: 0,
  rule_preview: 1,
  diagnosis: 2,
  finding: 2,
  explainer: 3,
  action: 4,
};

/** At most `max` cards, settings cards first and actions last; the rest in the same order for the "N more" line. */
export function capCards<T extends { slot: CardSlot }>(
  cards: T[],
  max: number = MAX_VISIBLE_CARDS,
): { shown: T[]; rest: T[] } {
  if (cards.length <= max) return { shown: [...cards], rest: [] };
  const ranked = cards
    .map((card, index) => ({ card, index }))
    .sort((a, b) => CARD_PRIORITY[a.card.slot] - CARD_PRIORITY[b.card.slot] || a.index - b.index);
  const keep = new Set(ranked.slice(0, Math.max(0, max)).map((entry) => entry.index));
  return {
    shown: cards.filter((_card, index) => keep.has(index)),
    rest: ranked.filter((entry) => !keep.has(entry.index)).map((entry) => entry.card),
  };
}
