import {
  streamAssistantChat,
  type AssistantChunk,
  type AssistantTurn,
} from 'src/services/settingsAssistant/settingsAssistantService';
import type { SessionChange } from 'src/utils/assistantSessionChanges';
import { getAuthorizationToken } from 'src/pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { OpenAPI } from 'src/generated-api-sdk/core/OpenAPI';
import {
  parseAiTagPreview,
  parseAiTagSuggestion,
  parseDiagnosis,
  stoppedPreview,
  type AiTagPreview,
  type AiTagSuggestion,
  type DiagnosisResult,
  type DiagnosisSymptom,
} from 'src/utils/validationAssistant/diagnosis';

export const VALIDATION_CHAT_PATH = '/v3/validation-assistant/chat';

export interface ValidationAssistantRequest {
  doc_id: string;
  messages: AssistantTurn[];
  language?: string;
  conversation_id?: string;
  // the assistant's own applied changes, masked
  session_changes?: SessionChange[];
  // CORE-6161: the screen the panel is on; the server puts that context first
  screen?: AssistantScreen;
}

export type AssistantScreen = 'validation' | 'po_match' | 'accounting';

export const DIAGNOSIS_PATH = '/v3/validation-assistant/diagnosis';
export const AI_TAGS_SUGGEST_PATH = '/v3/validation-assistant/ai-tags/suggest';
export const AI_TAGS_PREVIEW_PATH = '/v3/validation-assistant/ai-tags/preview';
export const AI_TAGS_APPLY_PATH = '/v3/validation-assistant/ai-tags/apply';
export const AI_TAGS_UNDO_PATH = '/v3/validation-assistant/ai-tags/undo';

export class DiagnosisRequestError extends Error {
  status: number;
  code: string;
  body: Record<string, unknown>;
  constructor(message: string, status = 0, code = '', body: Record<string, unknown> = {}) {
    super(message);
    this.name = 'DiagnosisRequestError';
    this.status = status;
    this.code = code;
    this.body = body;
  }
}

export interface DiagnosisRequest {
  doc_id: string;
  symptom?: DiagnosisSymptom;
  table_name?: string | null;
  lang?: 'de' | 'en';
}

export interface AiTagPreviewRequest {
  doc_id: string;
  tags: string[];
  table_name?: string | null;
  sample_size?: number;
}

export interface AiTagApplyResult {
  operation_id: string;
  undo_expires_in_seconds: number;
  supplier_label: string | null;
  /** the server also rewrote this document's stored table */
  table_written: boolean;
}

export interface AiTagSuggestRequest {
  doc_id: string;
  wish?: string;
  wanted_column?: string | null;
  table_name?: string | null;
}

function query(params: Record<string, string | null | undefined>): string {
  const q = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value) q.set(key, value);
  }
  return q.toString();
}

async function requestJson(
  method: 'GET' | 'POST',
  path: string,
  body?: unknown,
  signal?: AbortSignal,
): Promise<unknown> {
  const token = await getAuthorizationToken();
  const orgId = getOrgId();
  const response = await fetch(`${OpenAPI.BASE}${path}`, {
    method,
    headers: {
      ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}),
      Authorization: token || '',
      ...(orgId ? { 'X-ORG-ID': orgId } : {}),
    },
    body: body !== undefined ? JSON.stringify(body) : undefined,
    signal,
  });
  let payload: unknown = null;
  try {
    payload = await response.json();
  } catch {
    payload = null;
  }
  if (!response.ok) {
    const err = (payload && typeof payload === 'object' ? payload : {}) as Record<string, unknown>;
    throw new DiagnosisRequestError(
      typeof err.message === 'string' ? err.message : `HTTP ${response.status}`,
      response.status,
      String(err.error_code ?? ''),
      err,
    );
  }
  return payload;
}

/** CORE-6161: free-text questions about one document's validation blockers. */
export const validationAssistantService = {
  chat(
    request: ValidationAssistantRequest,
    signal?: AbortSignal,
  ): AsyncGenerator<AssistantChunk> {
    return streamAssistantChat(
      VALIDATION_CHAT_PATH,
      {
        doc_id: request.doc_id,
        messages: request.messages,
        language: request.language,
        conversation_id: request.conversation_id,
        ...(request.session_changes?.length
          ? { session_changes: request.session_changes }
          : {}),
        ...(request.screen && request.screen !== 'validation' ? { screen: request.screen } : {}),
      },
      signal,
    );
  },

  async diagnose(request: DiagnosisRequest, signal?: AbortSignal): Promise<DiagnosisResult> {
    const q = query({
      doc_id: request.doc_id,
      symptom: request.symptom,
      table_name: request.table_name,
      lang: request.lang,
    });
    const result = parseDiagnosis(await requestJson('GET', `${DIAGNOSIS_PATH}?${q}`, undefined, signal));
    if (!result) throw new DiagnosisRequestError('bad response');
    return result;
  },

  async suggestAiTags(request: AiTagSuggestRequest, signal?: AbortSignal): Promise<AiTagSuggestion> {
    const q = query({
      doc_id: request.doc_id,
      wish: request.wish,
      wanted_column: request.wanted_column,
      table_name: request.table_name,
    });
    const result = parseAiTagSuggestion(await requestJson('GET', `${AI_TAGS_SUGGEST_PATH}?${q}`, undefined, signal));
    if (!result) throw new DiagnosisRequestError('bad response');
    return result;
  },

  // 429 STOPPED (two rounds without the column) comes back as a "stopped" preview, not an error
  async previewAiTags(request: AiTagPreviewRequest, signal?: AbortSignal): Promise<AiTagPreview> {
    let raw: unknown;
    try {
      raw = await requestJson(
        'POST',
        AI_TAGS_PREVIEW_PATH,
        {
          doc_id: request.doc_id,
          tags: request.tags,
          ...(request.table_name ? { table_name: request.table_name } : {}),
          ...(request.sample_size ? { sample_size: request.sample_size } : {}),
        },
        signal,
      );
    } catch (err) {
      if (err instanceof DiagnosisRequestError && err.body.verdict === 'stopped') {
        return stoppedPreview(err.body);
      }
      throw err;
    }
    const result = parseAiTagPreview(raw);
    if (!result) throw new DiagnosisRequestError('bad response');
    return result;
  },

  async applyAiTags(previewToken: string): Promise<AiTagApplyResult> {
    const body = (await requestJson('POST', AI_TAGS_APPLY_PATH, { preview_token: previewToken })) as Record<
      string,
      unknown
    > | null;
    if (!body || typeof body.operation_id !== 'string') throw new DiagnosisRequestError('bad response');
    const scope = (body.rule_scope || {}) as Record<string, unknown>;
    return {
      operation_id: body.operation_id,
      undo_expires_in_seconds:
        typeof body.undo_expires_in_seconds === 'number' ? body.undo_expires_in_seconds : 0,
      supplier_label: typeof scope.supplier_label === 'string' ? scope.supplier_label : null,
      table_written: body.document_table_updated === true || body.document_table_written === true,
    };
  },

  async undoAiTags(operationId: string): Promise<{ table_restored: boolean }> {
    const body = (await requestJson('POST', AI_TAGS_UNDO_PATH, { operation_id: operationId })) as Record<
      string,
      unknown
    > | null;
    return { table_restored: body?.document_table_restored === true };
  },
};

export default validationAssistantService;
