/**
 * CORE-6249 — improvements of a document, cached per document + language.
 *
 * Module-level on purpose: the validation screen mounts the panel with `v-if`,
 * so a component-level cache would be lost on every close/reopen and spend the
 * server's read budget again. Entries expire after a TTL; there is no document
 * save/status event to hook into, so the TTL is the invalidation (and
 * `clearImprovementsCache` is there for one).
 */
import type { Explainer } from 'src/utils/validationAssistant/explainer';

export const IMPROVEMENTS_CACHE_TTL_MS = 10 * 60 * 1000;
const MAX_ENTRIES = 50;

const entries = new Map<string, { at: number; items: Explainer[] }>();

const keyOf = (docId: string, language: string) => `${docId}|${language}`;

export function getCachedImprovements(
  docId: string,
  language: string,
): Explainer[] | null {
  const key = keyOf(docId, language);
  const hit = entries.get(key);
  if (!hit) return null;
  if (Date.now() - hit.at >= IMPROVEMENTS_CACHE_TTL_MS) {
    entries.delete(key);
    return null;
  }
  return hit.items;
}

export function setCachedImprovements(
  docId: string,
  language: string,
  items: Explainer[],
): void {
  entries.set(keyOf(docId, language), { at: Date.now(), items });
  if (entries.size > MAX_ENTRIES) {
    const oldest = entries.keys().next().value;
    if (oldest !== undefined) entries.delete(oldest);
  }
}

/** One document, or everything. */
export function clearImprovementsCache(docId?: string): void {
  if (!docId) {
    entries.clear();
    return;
  }
  for (const key of [...entries.keys()]) {
    if (key.startsWith(`${docId}|`)) entries.delete(key);
  }
}
